quests[27642] = { id = 27642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through The Wreckage", description = "The Twilight's Hammer were damn thorough when they sacked our town.  Me and me brothers may well be the only ones that held'm back. I gotta be sure though.\n\nAs you're siftin' through the ruins, keep an eye out for the bodies of me kinsmen. I wanna know if dere were any survivors... or if it seems like some might have gotten away.", sourceObjective = "Search for the bodies of 12 Dunwald Victims.", completion = "That many dead, eh? Not seemin' likely that anyone outside of me brothers fought through it then. I guess I already expected as much.\n\nThanks for takin' the time to look for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27643] = { id = 27643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnelly Dunwald", description = "So you be lookin' to find us, and I be lookin' to find me brothers. It sounds to me like we got some common ground in there abouts.\n\nDonnelly's our eldest, and while his size shows it, his wits might not. He's usually up in the northern ruins - in the hovel. Do ya think you might go lookin' for him for me? It'd be a right comfort if I knew he were safe.", sourceObjective = "Find Donnelly Dunwald.", completion = "Hi friend! I don't think I know you... I'm Donnelly Dunwald.\n\nWhat's your name? I don't think I know you... Do I know you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27644] = { id = 27644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eoin Dunwald", description = "Eoin's one of the twins. He's got a penchant for the drink. You'll likely be findin' him over by the old well - the ale stores were in a building there.\n\nMind making him to pay his worrying sister a visit? Shouldn't take much convincin' if you can get to the ale first.", sourceObjective = "Find Eoin Dunwald.", completion = "Of all the buildings in all the towns to collapse, why'd it have to be this one?!", sourceObjectiveStatus = "unverified-source-field" }
quests[27645] = { id = 27645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cayden Dunwald", description = "Cayden's the other twin. He's got a thirst too, but not for ale. I'm sure he's been havin' a grand time of it since the Twilight came to our doorstep. Gettin' some of that aggression out of his system mayhaps.\n\nI'm thinkin' the best place to go lookin for him is at market row, by the old smithy. He used ta hang out there anyway, but since that place is swarmin' with the most Twilight, he's probably got all the more reason to be callin' it home now.\n\nBring'm back for me. In one piece would be nice.", sourceObjective = "Find Cayden Dunwald.", completion = "Well look at ya, all geared and fancy. Keely send you to keep an eye on old Cayden, eh? Won't be needin' it. I got these louts handled.\n\nHahah! They chose the wrong dwarf to be ambushin' today! Ahahahahah!", sourceObjectiveStatus = "unverified-source-field" }
quests[27646] = { id = 27646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Beak", description = "I lost me gryphon. Beak! Where are you Beak?!\n\nWanna help me find him? I know he's in da hovel. He hasta be.\n\nBeak?! Wheres are ya?\n\nI hope he's okay.", sourceObjective = "Help Donnelly find Beak in Dunwald Hovel.", progress = "Did you find'm?! Please?", completion = "You found'm! You found Beak! I like you, new friend!\n\nI'm gonna go show Keely. Keely like Beak too.", sourceObjectiveStatus = "unverified-source-field" }
quests[27647] = { id = 27647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything But Water", description = "Look, buddy. Either you're here to help me find some drink, or you're in the way.\n\nWhy don't ya go down to the old storehouse and look downstairs. I had a mighty suspicion that ol' bookkeeper up in there was sneaking sips between pages. I bet he has a keg in his basement!\n\nIf ya find anything, come straight back to me! No dallyin'... this is urgent!", sourceObjective = "Check the cellar Eoin Dunwald mentioned for a keg.", progress = "You stink of sober! Find me some drink!", completion = "Donnelly's belly! That's more like it. Good to not be dyin' of the thirst again.\n\nHere, have some. Good ol' Eoin's never so impolite as ta not share!", sourceObjectiveStatus = "unverified-source-field" }
quests[27648] = { id = 27648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into The Fire", description = "Fine, fine. You want a piece of the action? You can join in.\n\nLet me know when you're ready ta go.", sourceObjective = "Accompany Cayden Dunwald through the somewhat obvious ambush.", progress = "They keep comin an' I'll keep swinging!", completion = "A thing of beauty, isn't it? An' they keep comin' back for more. Love it!\n\nI'll go find Keely and settle her nerves in a bit. Just one more go through the row.", sourceObjectiveStatus = "unverified-source-field" }
quests[27649] = { id = 27649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Supply", description = "Hey bud. Seeing as how you're so friendly and great and all, think you might do a dwarf a favor?\n\nThese are Dunwald ruins... there's SURE to be more stock in some of these buildings. If you come upon more ale, bring it my way, will ya? A good dwarf can never have enough!\n\nI'm thinkin' I'll find my way back to Keely, so ya might have to hunt me down, but I'll try'n make it worth it to ya.", sourceObjective = "Collect 6 Barrels of Wildhammer Ale.", progress = "Where's me booze?", completion = "Woooooh! That's exactly what my belly needs!\n\nYou get me all the nice things.", sourceObjectiveStatus = "unverified-source-field" }
quests[27650] = { id = 27650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Again", description = "Ya should find Keely. She'll be eager for word.", sourceObjective = "Speak to Keely Dunwald at the Dunwald Holdout.", completion = "Thank you for bandin' my brothers back together. I know they're tough, but they're even tougher when they're side by side, and there's a lot of Twilight out there.\n\nYou're good to put a gal's heart at ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[27651] = { id = 27651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing It Like a Dunwald", description = "They already left to hunt down the ettin that lead the attack on Dunwald. I asked them to at least give ya a chance to catch up, but I'm not sure waitin's in their blood.\n\nThey made off towards the town square, in the center of the ruins. You should go join'm before ya miss out on all the fun.", sourceObjective = "Speak to Flynn Dunwald and aid the Dunwald brothers in killing Darunga.", completion = "Thanks for your help. You've got a warrior's spirit in ya - you coulda fooled me for a Wildhammer if it weren't for your... well.. you know.\n\nI know Firebeard sent you to unite us. My love for that dwarf runs shallow, but you know now we've got plenty of reasons to make enemies of Twilight. If you see him, tell him that when the battle starts, the Dunwald family will be there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27652] = { id = 27652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted. I suppose that's what I get for hiding amongst the sheep.\n\n<Mathias studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice bunch of guys. Dead now. They're made from the souls of the most skilled killers.\n\nWant to do me a favor? Hunt them down. Bring back their soul pendants.", sourceObjective = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "I'm not sure what I'm going to do with all of these. I'll probably fence them and donate the proceeds to the Stormwind orphanage.\n\nNow to find someone sick enough to buy such a thing. It'll probably be a goblin. Or, a gnome warlock.", sourceObjectiveStatus = "unverified-source-field" }
quests[27653] = { id = 27653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted, {class}. But that's part of the fun of hiding amongst the sheep.\n\n<Garona studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice for a group of dead guys. They're made from the souls of only the most skilled killers.\n\nDo me a favor? Hunt them down.\n\nThey wear their souls in pendants about their necks. Bring them back to me. Souls optional.", sourceObjective = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "What do you think I should do with all of these? Maybe I'll melt them down and have the metal imbued into a new dagger that I can thrust into Cho'gall's chest.\n\nThink there's time for that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27654] = { id = 27654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "No foray into the field would be complete without a good old-fashioned take-the-bad-guys-out kind of mission.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, I'm sure you'll have plenty of targets.\n\nHow you choose to kill them is up to you.", sourceObjective = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", progress = "Looks to me like you might need to take out a few more. I'm just saying.", completion = "None of us are too good to get our hands a little dirty. Or bloody, in this case.", sourceObjectiveStatus = "unverified-source-field" }
quests[27655] = { id = 27655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "There's nothing worse than a self-hating Twilight's Hammer cultist. Nothing! These idiots actually want to bring about the end of the world.\n\nThat marks them for extinction in my book.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, you should have no shortage of targets.\n\nI could care less how you choose to kill them.", sourceObjective = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", completion = "Feels good to get a little blood on your hands, doesn't it? Especially when that blood belongs to such self-deluded fools.", sourceObjectiveStatus = "unverified-source-field" }
quests[27656] = { id = 27656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Croc-Out", description = "The Stagalbog east of town is swarming with crocolisks. Swarming, you hear me? I've sold every bit of crocolisk you could imagine.\n\nCrocolisk hides, teeth, tails, tongues, eyes, you name it. My point is, they ain't sellin' anymore. There's too many crocs! We're over-supplied and under-demanded.\n\nSo since they're of no use to me, and they occasionally eat my guests, I need you to just kill the suckers. Do me the favor, eh? I'll be here negotiatin' things with your people.", sourceObjective = "Slay 8 Sawtooth Crocolisks.", completion = "All taken care of? Good to hear. Takes a load off my mind.\n\nNow I can focus on proper business for the fine folk of Marshtide and Stonard, weary from the war... and all that junk.", sourceObjectiveStatus = "unverified-source-field" }
quests[27657] = { id = 27657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Mathias spits.>\n\nWe need help. There's an Earthen Ring woman, Earthcaller Yevaa, southwest at the Elementium mine.\n\nShe and her goblin initiate need help with the shutting down the elemental portals hereabouts. I'm thinking that in exchange, she can help us with our problem.", sourceObjective = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than happy to lend you whatever assistance that I can.", sourceObjectiveStatus = "unverified-source-field" }
quests[27658] = { id = 27658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Garona spits.>\n\nI hate to say it, but we need help. There's an Earthen Ring woman, a draenei named Earthcaller Yevaa.  She and her pet goblin are southwest at the Elementium mine.\n\nThey need help with shutting down the elemental portals around here. In exchange, she can help us with our problem.", sourceObjective = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than willing to help you in any way that I can.", sourceObjectiveStatus = "unverified-source-field" }
quests[27659] = { id = 27659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Overload", description = "I used to be the caretaker of the Earthen Ring's portals here. But while we were away helping to save Deepholm, the Twilight's Hammer moved in and corrupted the area.\n\nThey're using powerful ascendants to guard our portals. That's where they've made a critical error.\n\nI want you to go to the portals and use the controllers to overload them. This will unleash all of the portal's energy, debilitating the ascendant. Slay it.", sourceObjective = "Slay Debilitated Apexar, Debilitated Aetheron, and Debilitated Edemantus.", completion = "The last portal is deep within the mine here, but we'll deal with that in a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27660] = { id = 27660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Loch", description = "I have no knowledge of any artifact that Cho'gall is crafting, but I think I know one that can help.\n\nCountess Verrall is the ancient spirit of Loch Verrall to the north. She has no love for the Twilight's Hammer, who have polluted her waters.\n\nSeek her for the wisdom that you seek.", sourceObjective = "Speak with Countess Verrall at Loch Verrall in the Twilight Highlands.", completion = "I know why you are here, {name}. Your reasons sing within your fluids.\n\nI know about the dead dwarf forgesmith polluting my lake. If you want to find out what his corpse remembers, you must earn it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27661] = { id = 27661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire the Cannon", description = "My arch-nemesis, Lord Cannon, has foolishly decided to throw his allegiance to the Twilight's Hammer.\n\nIn the past, we've coexisted with a shaky truce, but his change of heart leaves me little choice but to put an end to him. Or, I should say, if you want the information that you seek from the dead dwarf, you're going to kill Lord Cannon for me.\n\nSeek him at Cannon's Inferno to the southeast.", sourceObjective = "Slay Lord Cannon.", progress = "Lord Cannon's not dead. I'd know if he were.", completion = "I am pleased. Lord Cannon was always an unworthy adversary.\n\nVery well, {race}, I will help you gain the information which you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[27662] = { id = 27662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbinding", description = "Look, if there's one thing I know, it's elementals. I've been able to really gain an appreciation for how they feel. Let me tell you, they don't appreciate being enslaved one bit!\n\nSo, what I'm saying here is that if you were to free the enslaved elementals, I'm sure that not only would they show their gratitude, they'd also likely turn on their masters.\n\nSounds like a win-win to me, {name}.", sourceObjective = "Free 10 Enslaved elementals by slaying them at the Twilight Citadel.", completion = "What'd I tell you? Elementals aren't so bad after all, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27663] = { id = 27663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tastes Like Strider", description = "You there! Yes, you! You want a good word put in with the Trade Baron? Give me a hand!\n\nI heard you're the one that got all those makrura tails. They're wonderful, but not enough for proper swamp food. I need drumsticks for my gumbo!\n\nThere's plenty of swampstriders just outside town in the Sorrowmurk. I want the biggest drumsticks you can find!", sourceObjective = "Collect 9 Jumbo Swampstrider Drumsticks from Swampstriders.", progress = "Have you got those drumsticks?", completion = "Ah, good, good! Just what I needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27664] = { id = 27664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Volcanic Deck", description = "Now that you have gathered all of the Ember cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Volcanic Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Volcanic deck!   Congratulations!", completion = "So you have put together a deck of Embers.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27665] = { id = 27665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Hurricane Deck", description = "Now that you have gathered all of the Wind cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Hurricane Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Hurricane deck!   Congratulations!", completion = "So you have put together a deck of Hurricanes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27666] = { id = 27666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Tsunami Deck", description = "Now that you have gathered all of the Wave cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Tsunami Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Tsunami deck!   Congratulations!", completion = "So you have put together a Tsunami deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27667] = { id = 27667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Earthquake Deck", description = "Now that you have gathered all of the Stone cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Earthquake Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete an Earthquake deck!   Congratulations!", completion = "So you have put together a deck of Earthquakes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27668] = { id = 27668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay Attention!", description = "Listen, {race}. It's not that I don't appreciate the rescue and all, but this is a dire situation.\n\nYou have to pay better attention out there!\n\nI was watching, and you passed right over a busted alliance crate.\n\nThere's bound to be something in there that could help me and my boys.\n\nHow about you get out there and take a look-see, hrm?", sourceObjective = "Nazgrim wants you to see what lies in the broken Alliance crate north of The Immortal Coil.", completion = "Sure enough...\n\nThis looks to be something that Nazgrim will take quite an interest in.", sourceObjectiveStatus = "unverified-source-field" }
quests[27669] = { id = 27669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Honors", description = "It looks like all that's left to do is to place the orbs on the pedestals at each corner of this mechanism.\n\nWe appear to have stumbled upon what may be the most important find in modern history.\n\n<Harrison looks at you for a moment, then hands you the orbs.>\n\nWell, go ahead, {name}.\n\nWe'd have never made this discovery without you.", sourceObjective = "Use the Orbs of the Stars near the mechanism in the Chamber of the Stars.", completion = "Well, now. Would ya look at that!\n\nAs amazing as this is, I am confident that there's more to our discovery than meets the eye...\n\nMuch more.", sourceObjectiveStatus = "unverified-source-field" }
quests[27670] = { id = 27670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinned Down", description = "My name is Nevin Twistwrench and I'm the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E.\n\nI don't know how you managed to survive the radiation down here, {name}, but most of the others haven't fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They've lost their minds!\n\nIf you're still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?", sourceObjective = "Kill 6 Crazed Leper Gnomes.", progress = "Help my men get the way cleared out so we can help the other survivors get out of here!", completion = "Well done, {name}. My men can take it from here. Let's focus on getting the other survivors out now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27671] = { id = 27671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See to the Survivors", description = "If we don't do something quick, neither Nevin nor the survivors will make it out of here alive. I'm going to give you my squad's emergency teleport beacon. We still have enough strength and ammunition to fight our way out of here, but those survivors are in no condition to make a run for it.\n\nUse the beacon on survivors to arrange for them to be teleported out of here to the safe area my men have set up. Once you've done that, report back to me and we'll make arrangements to get you out of here.", sourceObjective = "Use the Teleport Beacon to teleport 6 Survivors to safety.", progress = "Nevin's team found a lot of survivors this time, but he's cutting it awful close.", completion = "I know Nevin will be pleased with all the survivors you managed to help. I still can't believe you managed to stay so strong down here in the radiation. You've seen the shape the other survivors are in.\n\nLet's get you to the loading room for decontamination.", sourceObjectiveStatus = "unverified-source-field" }
quests[27672] = { id = 27672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a door which leads to the legendary Chamber of Khaz'mul. Who knows what secrets could be hidden inside!\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to unlock the secrets of Uldaman!", sourceObjective = "Defeat Ironaya.", completion = "Don't worry about the chamber, my boys will check it out! You have more important things to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27673] = { id = 27673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's What's Inside That Counts", description = "The Makers built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI fear that one of the Old Gods is responsible for this, and you're going to help me see if that's the case! Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", sourceObjective = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Where are the cores, lad? By Muradin's Beard, where are the bloody cores?\n\n<Kand takes a deep breath.>\n\nSorry about that. Have you been able to obtain the cores?", completion = "This is incredible, {name}. The power coursing through each core...the contrasting powers so close together!\n\nI'll take this to the proper dwarves right away. These cores are extremely important!", sourceObjectiveStatus = "unverified-source-field" }
quests[27674] = { id = 27674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Surface", description = "Nevin has just sent word that he and his men are making their way to the surface. He'll be waiting for you in the building that S.A.F.E. has established as its headquarters.\n\nSee Torben Zapblast over there? Talk to him when you're ready to head to the surface and he'll arrange to have you transported up there. It's been a pleasure meeting you, {name}, and I'm honored to have played a small role in helping you escape from Gnomeregan to start your life on the surface.", sourceObjective = "Speak to Torben Zapblast to get teleported to the surface and report to Nevin Twistwrench.", completion = "It's good to see you again, {name}. Without your help, we wouldn't have been able to get so many survivors out of Gnomeregan this time. Everyone is going to be thrilled to meet you and hear your story.", sourceObjectiveStatus = "unverified-source-field" }
quests[27675] = { id = 27675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Stormwind City to accept your forged documents.", sourceObjective = "Find a resident of Stormwind City to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27676] = { id = 27676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Explorers' League is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", sourceObjective = "Kill Galgann Firehammer.", completion = "Fantastic! Great work! We'll know all that Dig Three has to tell us in no time at all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27677] = { id = 27677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. The secrets on these discs could change everything about how we view our world. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe problem is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for the Explorers' League!", sourceObjective = "Defeat Archaedas.", completion = "Well done, lad! Now go to the discs and learn all you can!", sourceObjectiveStatus = "unverified-source-field" }
quests[27679] = { id = 27679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a locked door which I believe leads to the legendary Chamber of Khaz'mul. We do not yet know what artifacts wait inside it.\n\n\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to progress any further into this place.", sourceObjective = "Defeat Ironaya.", progress = "Were you able to access the chamber, or should I choose to spend my time on more experienced adventurers in the future?", completion = "Reliquary agents are en route to investigate the chamber. You have more important matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[27680] = { id = 27680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. These platinum discs could grant our order unbelievable power. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe only problem in obtaining them is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for The Reliquary.", sourceObjective = "Defeat Archaedas.", completion = "You are a most reliable agent, {name}. Proceed to the discs and learn all you can. Report back to me immediately after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27681] = { id = 27681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Reliquary is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", sourceObjective = "Kill Galgann Firehammer.", progress = "Was old Galgann too much for a lowly {class}?", completion = "Well done. Dig Three and any secrets beyond that door will soon be ours and ours alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[27682] = { id = 27682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Minerals", description = "The Titans built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI suspect that one of the Old Gods is responsible for this, and you're going to help me see if that is indeed true. Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", sourceObjective = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Do you have the cores with you, or are you just here to chat? Perhaps we should stop this whole charade and enjoy some snacks and fine wine instead?", completion = "Both of these cores are still far more potent than most of the cores we use  to power our own protectors, and these are ancient devices!\n\nThank you, these will prove extremely valuable to our society.", sourceObjectiveStatus = "unverified-source-field" }
quests[27683] = { id = 27683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Woods", description = "I saw the strangest commotion coming through town the other day.  A horse-drawn cart, loaded with crates and chests, a worgen woman at the reins, a blood elf by her side, and a dwarven paladin running behind, yelling some of the most creative obscenities I've heard in quite some time.\n\nThey looked like they were headed to Eastern Plaguelands, though I'd imagine they can't be far past the Thondroril River by now.  I wonder what they were up to?", sourceObjective = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[27684] = { id = 27684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visitors", description = "My sources at the Menders' Stead have informed me that we will be having some visitors soon.  A group of paladins - led by a worgen tradeswoman, of all things - will be arriving here shortly.  I look forward to meeting them.  Particularly one of them.\n\nWould you mind stopping in and checking in on them?  I can't say for sure, but by the time you get there, they should just be crossing the Thondroril River, far to the west.", sourceObjective = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[27685] = { id = 27685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Deed Left Undone", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nSo... in our rush ta git over here, we left a little unfinished business off to the east a ways.\n\nA little lady was near death herself. We had no choice but ta leave her by a little air vent when we came here to yer rescue.\n\nHow bout yeh git over and help her while there's still time?", sourceObjective = "Speak to Adarrah in the Kelp'thar Forest.", completion = "Oh, finally...\n\nI don't know how much longer I can last!", sourceObjectiveStatus = "unverified-source-field" }
quests[27686] = { id = 27686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Orgimmar to accept your forged documents.", sourceObjective = "Find a resident of Orgimmar to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27687] = { id = 27687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opened Can of Whoop Gnash", description = "What an accomplishment, felling a  mighty sea giant!\n\nThe new residents of Smuggler's Hole will feel considerably safer knowing this monster is no longer loitering outside their haven.", sourceObjective = "Bring Gnash's Head to Samir in Smuggler's Hole.", progress = "You took down that Sea Giant, {class}?", completion = "It's not much, but it's all I've got down here.\n\nYou're more than welcome to it, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27688] = { id = 27688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that we need to eliminate: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI'd like for you to serve as my distraction. When the time is right, I'll step in and finish them off from behind.\n\nWhatever you do, {name}, do not underestimate them. Each got to where they are by being ruthless and very good at what they do.", sourceObjective = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight.\n\nWe work well together, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27689] = { id = 27689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that need killing: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI want you to serve as a distraction. When the time is right, I'll step in to finish them off from behind.\n\nJust make sure that whatever you do, you don't underestimate them, {name}. Each of those lunatics got to where they are by being ruthless and very good at what they do.", sourceObjective = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight. Not bad work, {name}. Not bad at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27690] = { id = 27690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, the Drake-Tamer", description = "{name}, the stronghold at Bloodgulch is the heart of the Dragonmaw empire in the Highlands. It is just up the river. Narkrall Rakeclaw is using his considerable power to amass a wing of drake-riders there.\n\nFor the Dragonmaw to succeed, Bloodgulch must succeed. Go to Narkrall and make sure it is so.", sourceObjective = "Report to Narkrall Rakeclaw at Bloodgulch in the Twilight Highlands.", completion = "<Narkrall sizes you up.>\n\nAnother mewling Horde whelp? Zaela saps our strength by diluting our forces with the weak. Very well, {class}. Prove yourself to me, and show me what your Horde is made of.", sourceObjectiveStatus = "unverified-source-field" }
quests[27691] = { id = 27691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshfin Madness", description = "I'm afraid the rest of the Steamwheedle here are gone. All the young ones at the camp to the east were lost when the murlocs came.\n\nYes, there's always been murlocs on these shores... but not in these numbers. They came in droves from the sea at night, howling and frothing, swarming up onto the land to attack!\n\nWe can't have them still running around, now can we? Would you put an old goblin at ease and go beat some of them back into the water?", sourceObjective = "Slay 12 Marshfin Murlocs.", completion = "You have to wonder just what's out there. This is the coast of the Forbidding Sea, with nothing beyond its reaches... but all these fishy folk just stomped right out of it.\n\nWhat's more, I saw where they've been going...", sourceObjectiveStatus = "unverified-source-field" }
quests[27692] = { id = 27692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Princess Theradras", description = "Do not be alarmed, young {race}. I am Zaetar, son of Cenarius, and I come to you for your assistance.\n\nLong ago, I made the mistake of mating with Princess Theradras, a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras' taint runs deep and threatens far more than just Maraudon.\n\nCome slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.", sourceObjective = "Kill Princess Theradras  and return to Zaetar's Spirit.", completion = "Thank you, {name}. As you can see, my mere presence here has resulted in a bloom of glorious life despite my mate's presence. Names aside, perhaps one day you will again venture into Desolace and find it a verdant oasis free of any traces of the Old Gods.", sourceObjectiveStatus = "unverified-source-field" }
quests[27693] = { id = 27693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", sourceObjective = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", sourceObjectiveStatus = "unverified-source-field" }
quests[27694] = { id = 27694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Tears", description = "The trolls that lurk within this temple have done grievious harm to my kind, {name}. We were sent here to guard this place, and were instead used to unleash the terrible powers within.\n\nI must beg you for the help only a mortal can give. You can be my hand within the temple; should I enter by myself, I risk being turned against my brothers as well.\n\nWe shall make a pact. If you wish to help, first gather Atal'ai artifacts from the waters around the temple, and return them to me.", sourceObjective = "Collect 5 Atal'ai Artifacts from the Pool of Tears surrounding the Temple of Atal'Hakkar.", progress = "Your gathering of these artifacts will be a sign of faith. Once rendered, I will perform the ritual.", completion = "The essence of the green dragonflight wafts from these artifacts; the vestiges of my corrupted kin. In purifying them, I form a bond between us.\n\nStep forward, {name}, and receive the Oathstone of Ysera's Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[27695] = { id = 27695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed too many red dragons, but one yet lives. Do you remember Lirastrasza? She's shackled nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut through her chains.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", sourceObjective = "Obtain the Elementium Axe.", progress = "Do you have the axe? They're going to kill Lirastrasza soon.", completion = "That thing looks sharp. Sharp enough to do the deed, at least.\n\nBut if I'm a judge of weaponry, that's not what Cho'gall's after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27696] = { id = 27696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed many red dragons, but one's still breathing. Do you remember Lirastrasza? She's chained nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut her free.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", sourceObjective = "Obtain the Elementium Axe.", progress = "Do you have the axe?", completion = "That's a very sharp axe. It'll do the job, but if I'm any judge of weaponry, that's not what Cho'gall's after.", sourceObjectiveStatus = "unverified-source-field" }
quests[27697] = { id = 27697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption in Maraudon", description = "{name}, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon.\n\nLord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!", sourceObjective = "Kill Lord Vyletongue and return to Zaetar's Spirit.", completion = "Excellent work, {name}! Eliminating Vyletongue's presence is a key step to freeing me and, ultimately, saving these lands from corruption. Take this as a token of my thanks and an incentive to continue your work here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27698] = { id = 27698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Theradras", description = "Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon. Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction.\n\n{name}, venture forth and kill Noxxion and Razorlash. They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.", sourceObjective = "Kill Noxxion and Razorlash and return to Zaetar's Spirit.", completion = "Without her powerful servants, Princess Theradras is significantly more vulnerable. Find her lair, {name}...it is time to strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[27699] = { id = 27699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Weak", description = "That's one tough shark!\n\nYou determine that it's in everyone's best interest to try and distract Budd and hope his attention never returns to Gnaws and this Skeletal Reef.\n\nPerhaps the teeth of the beast will prove captivating enough...", sourceObjective = "Collect 5 of Gnaws' teeth from the Skeletal Reef.", progress = "Whatcha got there, pal?", completion = "What?!\n\nGnaws ain't dead?!\n\nThis kinda takes the quick outta my get rich quick scheme...\n\nThem giant shark teeth are nice and all, but we can't stop 'til that shiney is ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[27700] = { id = 27700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her.\n\nI need you to take the Elementium Axe and free her from her bonds.", sourceObjective = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", progress = "Use the axe to break Lirastrasza's chains.", completion = "Isn't she a beauty?\n\nLet's see what she does now that she's free.", sourceObjectiveStatus = "unverified-source-field" }
quests[27701] = { id = 27701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her, {class}.\n\nYou need to take the Elementium Axe and free her from her bonds before they do.", sourceObjective = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", progress = "All you have to do is use the axe to break Lirastrasza's chains.", completion = "Isn't she beautiful? So graceful.\n\nI hope she gets her fill of revenge and then some.", sourceObjectiveStatus = "unverified-source-field" }
quests[27702] = { id = 27702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are drakes that she's downing that need finishing off, {name}. Wouldn't want the Twilight's healers to get them back up into the air.\n\nTime for a little Coup de Grace.", sourceObjective = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", progress = "Finish off more Twilight Skyterrors.", completion = "Our efforts to improve relations with the red dragons has really paid off, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27703] = { id = 27703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are still drakes that she's downing that need finishing off, {name}. We don't want the stinking Twilight healers to get them back up into the air.\n\nTime for a little Coup de Grace.", sourceObjective = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", progress = "That's all? I think that you can finish off a few more.", completion = "Good thing that you and Warlord Krogg made friends with the red dragons.", sourceObjectiveStatus = "unverified-source-field" }
quests[27704] = { id = 27704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of the Sunken Temple", description = "I will need you to enter the temple first, {name}. I can join you once a path is secure, but I dare not enter blindly. Turned against my kind, I would be a vicious enemy.\n\nYou can start by descending the stairs behind me. Then, swim through the flooded depths of the Broken Hall. Once there, follow the passageway to the right to find the Hall of Masks.\n\nBeware of any temple guards. Once you have found the Hall of Masks, I will contact you through the Oathstone.", sourceObjective = "Journey through the antechambers of the temple to the Hall of Masks.", progress = "You must not falter, {name}. Your actions will pave the way for me to enter the temple myself.", completion = "This is it!\n\nThese are the bones of my kin...", sourceObjectiveStatus = "unverified-source-field" }
quests[27705] = { id = 27705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step One: The Priestess", description = "My bretheren are being butchered here. It's as I thought.\n\nI must ask your help further before I enter, {name}. In the passageway outside this room, the hallway proceeds left and right. To the right, it goes down to the Chamber of Blood. Here the Atal'ai perform their dark rituals.\n\nThey have expected and prepared for my kind for years, but not for you. Enter the Chamber of Blood and slay the Priestess Udum'bra. She is one of three foul presences here that must be vanquished before I may enter.", sourceObjective = "Slay Priestess Udum'bra in the Chamber of Blood.", completion = "Good riddance. Another source of corruption in this world put to rest.\n\nI thank you for your bravery, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27706] = { id = 27706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scepter of Orsis", description = "The chest below unlocks with a loud click as you insert the two stones into the plaque.\n\nObtain the scepter and bring it back to General Ammantep.", sourceObjective = "Obtain the Scepter of Orsis from the Sacred Receptacle.", progress = "You're back, {name}!", completion = "So... this is what Al'Akir wanted all along.", sourceObjectiveStatus = "unverified-source-field" }
quests[27707] = { id = 27707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neferset Prison", description = "Hieroglyphs depicting a chained Tol'vir mark the southeastern corner of the map.\n\nPerhaps Tahet was brought there when he was imprisoned.", sourceObjective = "Go to the Neferset Prison Camp and find the whereabouts of Tahet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27708] = { id = 27708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Time", description = "<Erunak's image penetrates your mind.>\n\nYou have done well, {name}, but more remains to be done.\n\nBefore moving on from this place, let us be sure that we leave it in disarray.\n\nFind the one who leads these naga and repay him for his misdeeds.", sourceObjective = "Erunak Stonespeaker wants you to slay Warden Azjakir at The Clutch.", progress = "Is it done, {name}?", completion = "It is good that this operation has been undone.\n\nSoon, I must move on...", sourceObjectiveStatus = "unverified-source-field" }
quests[27709] = { id = 27709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", sourceObjective = "Complete the Sentinel's Game by connecting the two red statues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27711] = { id = 27711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller's initiate, Goldmine, has need of you.\n\nI think that they're ready for you to help them with whatever's down in that mine.", sourceObjective = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "{name}, glad you're back! Have I got something fun for us to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27712] = { id = 27712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller has a goblin initiate? Goldmine is his name? He has need of you.\n\nI think that they're ready for you to do their dirty work with whatever's down in that mine.", sourceObjective = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "{name}, glad you're back! Have I got something fun for us to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27713] = { id = 27713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came", description = "Deathwing made quite a mess when he passed through these parts.  If it weren't for me, he'd probably still be here, layin' waste to all the good people of the Badlands.\n\nWhat, you don't believe me?  Fine, let me tell you the whole story.", sourceObjective = "Listen to Theldurin's tale.", progress = "Are you going to listen or not?", completion = "Some story, huh?  Now you know why Deathwing hasn't come back here since.", sourceObjectiveStatus = "unverified-source-field" }
quests[27714] = { id = 27714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: The Real Story", description = "Not only was Theldurin's story wrong, it was boring, unimaginitive, and slow.\n\nI'll tell you how things really happened on that day.", sourceObjective = "Listen to Lucien Tosselwrench's version of the story.", progress = "I'm not done with my story yet.  Sit back down.", completion = "The end!  No moral.", sourceObjectiveStatus = "unverified-source-field" }
quests[27715] = { id = 27715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: What Really Happened", description = "These two have no idea how to tell a story.  Theldurin's story was too short, and Lucien's tale was a little too tall, if you catch my drift.\n\nAlso, neither of their stories had action and fans admiring my awesomeness in them.\n\nSit back, {name}.  I'll tell you what really happened that day.", sourceObjective = "Listen to Martek the Exiled's version of the story.", progress = "I seem to have lost my place... let's see... where was I...", completion = "I can't believe those guys would interrupt me like that.  My story was going so well, too...\n\nAnyhow, thanks for sticking around so long.  It's nice to have someone new to share tall tales with.  I'm sure Lucien and Theldurin feel the same way.\n\nYou have any you'd like to share with us?", sourceObjectiveStatus = "unverified-source-field" }
quests[27716] = { id = 27716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Levia Dreamwaker, back with the Nespirah survivors, was looking for something exactly like this.>", sourceObjective = "Bring the Ancient Elven Etching to Levia Dreamwalker. You should find her with the Alliance Nespirah Survivors.", progress = "Hah! Did you see the admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! It will take me a while to translate, but this is precisely the kind of find I was hoping for.\n\nThere's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. Here... perhaps I have something that may be of use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27717] = { id = 27717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Elendri Goldenbrow, back with the Nespirah survivors, was looking for something exactly like this.>", sourceObjective = "Bring the Ancient Elven Etching to Elendri Goldenbrow. You should find her with the Horde Nespirah Survivors.", progress = "Hah! Did you see the captain giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! I can't have expected much more with the tools I gave you.\n\nI should be able to fill in the blanks and get this all written out shortly. There's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. You're not bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27718] = { id = 27718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Vashj'ir!", description = "All able-bodied members of the Horde are hereby ordered to report to Commander Thorak at Bladefist Bay in Durotar.\n\nNow, more than ever, your help is needed in battling our most hated enemy, the Alliance!\n\nTo reach Bladefist Bay you must travel south through the main gates of Orgrimmar and enter Durotar. From there, follow the path east to the coast. Thorak will be standing at his post near the docks.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to Commander Thorak at Bladefist Bay in Durotar.", completion = "Lok'tar, brother! You have arrived just in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27719] = { id = 27719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen, take your information and be gone from my demesne.", sourceObjective = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", progress = "What information did you uncover concerning Cho'gall's weapon?", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[27720] = { id = 27720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", sourceObjective = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[27721] = { id = 27721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Mount Hyjal!", description = "All able-bodied members of the Horde are hereby ordered to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Blackhoof to gain entry into Moonglade. Blackhoof is located at the tauren district in the Valley of Wisdom in Orgrimmar.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", progress = "Blackhoof sent you?", completion = "We knew the Horde would send help and not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27722] = { id = 27722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Deepholm!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Krogar at the Western Earthshrine in Orgrimmar.\n\nThe Earthen Ring, lead by our former Warchief, Thrall, requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world!\n\nThe Western Earthshrine can be found just north of the Valley of Wisdom.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Speak with Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27724] = { id = 27724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Vashj'ir!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Recruiter Burns in Stormwind Harbor.\n\nRecent attacks by the Horde on our trade ships must be met with swift and just force!\n\nStormwind Harbor can be found in the northwest region of Stormwind City.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship.", sourceObjectiveStatus = "unverified-source-field" }
quests[27725] = { id = 27725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quel'Danil Lodge", description = "I may appear far from home to you, {class}, but quite a few of my people were led here by Ambassador Rualeth. We have settled with the high elves of the Quel'Danil Lodge, to the northwest, to train in the ways of the Light and enjoy the peaceful beauty of this land.\n\nSuch peace may be short lived. We have seen the Horde moving further west from here. Could you travel to Quel'Danil and give warning to Anchorite Traska? Her cabin is just north of the main lodge.", sourceObjective = "Speak with Anchorite Traska at the Quel'Danil Lodge.", completion = "Yoro sends warning of the Horde? The Highvale have been cautious of an attack for some time now. In fact, we have been--\n\n<Screams and the clash of metal break out to the south.>\n\nBy the light... they are here!", sourceObjectiveStatus = "unverified-source-field" }
quests[27726] = { id = 27726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade.", progress = "Help us!", completion = "We knew the Alliance would send help and not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27727] = { id = 27727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Deepholm!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.\n\nThe Earthen Ring requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world and destroy all life on Azeroth!\n\nThe Eastern Earthshrine can be found directly northwest of Stormwind Keep.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", sourceObjective = "Speak with Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27729] = { id = 27729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, With Eeling", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", sourceObjective = "Kill 8 of any Eel in the Kelp Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27733] = { id = 27733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Ol' Switcheroo", description = "Look, I'd love to give the order and have my men blast these rebels to bits right now, but I can't because the entire Stockade is under Warden Thelwater's jurisdiction, and he only wants to contain them right now.\n\nRather than disobey orders, we're going to take care of this in a slightly different manner! We've managed to befriend Mortimer Moloch, who just so happens to be the ruthless rebel leader Randolph Moloch's twin. Kill Randolph, and we'll switch 'em so Mortimer can stop the rebellion peacefully!", sourceObjective = "Kill Randolph Moloch.", progress = "We can't make the switch until Randolph is dead!", completion = "Yes, Mortimer just faked his own death. He'll probably take on his brother's name and continue on his 'epic schemes'. We'll just have to deal with that when the time comes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27737] = { id = 27737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Fire Be Saved!", description = "I'm well-versed in first aid and other forms of healing, and with the help of my Lightwell I've been able to nurse many of our men back to full health. The problem we still have is that it's so cold and damp down here that I'm losing them anyways, despite healing their wounds!\n\nThe quakes angered the elements that reside in the prison...when they erupted out of the earth they slaughtered half of the prisoners. If you slay their leader, Lord Overheat, and bring me his core I can use it to warm our men!", sourceObjective = "Obtain Lord Overheat's Fiery Core.", progress = "Do you have the core? Our men are dying in here!", completion = "Thank goodness! With this fire, our men will live through this ordeal!\n\nThank you so much, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[27738] = { id = 27738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Scales", description = "A spot on the southern end of the map was marked with hieroglyphs of crocodiles fighting each other.\n\nThat must be where Caimas took Tahet.\n\nGo to the Pit of Scales and find a way to rescue the Vizier's son.", sourceObjective = "Rescue Tahet at the Pit of Scales in Uldum.", progress = "{name}?", completion = "I thank you for what you've done, {name}.  You can count on my vote when High Council convenes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27739] = { id = 27739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnoll King", description = "{name}, I'm afraid I must ask of you the impossible.\n\nI received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here.\n\nDoing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces.\n\nYou must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.", sourceObjective = "Defeat Hogger.", progress = "Have you defeated Hogger?", completion = "You have performed a deed this day unlike any I have seen in my long career. Hogger's death will plague the Riverpaw for years to come, and hopefully put an end to their attacks on our people.\n\nGreatest of heroes, please take this as a sign of my eternal gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[27740] = { id = 27740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baba Bogbrew", description = "Hey, while you were out, the Baron stopped by! He kicked me until money came out!\n\nHe always does that though. But this time he asked me to tell you something! He wants you to go south and help out our herbalist, Baba Bogbrew.\n\nShe's all the way across the water! But just talk to my girl Daisy outside and she'll send you there the Crazy Larry way!", sourceObjective = "Talk to Lil' Crazy Daisy to take a cannon ride to Baba Bogbrew.", completion = "Ah, it's so nice to have help dropped in.\n\nModern convenience... I can't get enough of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27742] = { id = 27742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little on the Side", description = "You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff!\n\nWhat a waste!\n\nSo, what do you say? 90/10 my way?", sourceObjective = "Collect 6 Elementium Shards.", progress = "How much do you think you can carry?", completion = "<Goldmine slyly looks at the pile of Elementium shards.>\n\nHmm, I don't think that stuff's going to sell for much. I better give you your cut right now so you don't feel ripped off.", sourceObjectiveStatus = "unverified-source-field" }
quests[27743] = { id = 27743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While We're Here", description = "You know, while we're here, we might as well take care of the Twilight's Hammer intruders. This place used to be ours, after all!\n\nI'd help, but with my totems and weapons broken, I'm pretty helpless.", sourceObjective = "Slay 12 Twilight's Hammer cultists, either Depths Overseer or Twilight Miners, within the Elementium Depths.", progress = "Let's take care of a few more of them, okay?", completion = "They had it coming to them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27744] = { id = 27744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Ruination", description = "Examining the Twilight Rune of Earth, you can almost feel its power extending further into the Elementium Depths.\n\nIt's probably connected to other runes. Initiate Goldmine thinks that you should destroy all of them.", sourceObjective = "Destroy the Twilight Rune of Earth, Rune of Water, Rune of Air, and Rune of Fire.", progress = "We still have some runes to destroy, {name}.", completion = "That'll teach 'em to move in on our territory!\n\nWhat's that over across the way?", sourceObjectiveStatus = "unverified-source-field" }
quests[27745] = { id = 27745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fiery Reunion", description = "That's Magmatooth, my estranged fire elemental. {name}, you gotta kill him or he's gonna kill me!\n\nIt was all just a big misunderstanding. How was I to know he'd be mad about me \"borrowing\" his heart down in Deepholm? He can't die... not permanently anyway!\n\nHe's got the controller to the portal on him for sure. You gotta get the controller and then use it in the Fire portal to take us back to the entrance.", sourceObjective = "Obtain the Fire Portal Controller and use it at the Fire Portal.", progress = "{name}!", completion = "We survived and all of the portals are now shutdown!\n\nYou don't think Magmatooth is going to hold a grudge, do you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27746] = { id = 27746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empire of Dirt", description = "This war has taken its toll on us as a people. We have lost much to secure our place as the rightful rulers of Lordaeron. And though the moment is won, the battle continues to rage in other parts of the Eastern Kingdoms.\n\nI must return to the Undercity to recuperate. I want you to go to Hillsbrad Foothills in my stead, {name}. As my most trusted soldier, you will lead our forces to absolute domination against our enemies in Hillsbrad.\n\nReport to High Executor Darthalia at Southpoint Blockade, to the east.", sourceObjective = "Report to High Executor Darthalia at Southpoint Blockade in Hillsbrad Foothills.", completion = "News of your conquest in Silverpine emboldens us, {name}. We are prepared to fight at your command and beat back the last remaining vestiges of humanity in Hillsbrad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27747] = { id = 27747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total War", description = "Many of the Wildhammer have already fled their homes. It is time to wipe them from the map.\n\nUp on the ridge to the north you will find abandoned houses in the Thundermar Ruins. Kegs of potent Thundermar ale have been left behind.\n\nThundermar ale is 220 proof; I don't know how that's possible.\n\nSmash open the kegs and set their content aflame. Burn them out! Leave the dwarves nothing to return to!", sourceObjective = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27748] = { id = 27748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortune and Glory", description = "We have to keep moving, {name}. It's just a matter of time before those troops get their act together.\n\nThe coffer should be just beyond these ruins.\n\nStay on your toes. Something tells me this isn't over yet...", sourceObjective = "Kill the Obsidian Colossus.", completion = "Good to see you're still in one piece, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27750] = { id = 27750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Forage", description = "<Griff's stomach growls.>\n\nWhenever we Dragonmaw go on the warpath, everyone stops hunting.\n\nThe best tasting food is stolen from the mouths of the enemy. Up on the ridge north of the river there's a bunch of wrecked Wildhammer houses. I bet they're loaded with food.\n\nBring some to my mouth.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Hungry.", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! Did you get any for yourself?", sourceObjectiveStatus = "unverified-source-field" }
quests[27751] = { id = 27751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Wildhammer", description = "Since my people first claimed the Highlands, the Wildhammer dwarves have been our persistent foe. We fought them in Grim Batol, we fought them in the Wetlands, and even now open warfare rages to our north, across the river, amidst the Thundermar Ruins.\n\nProve your valor to me. Seek out and crush Wildhammer Warbrands. The best among them carry insignias - my warriors collect them by the dozen.\n\nCan you?", sourceObjective = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, {class}.", completion = "<Narkrall clenches the insignias in his weathered hand.>\n\nSo, {class}. There's more to you than meets the eye.\n\nMaybe your Horde can stand with the best of my warriors. Let's try you out...", sourceObjectiveStatus = "unverified-source-field" }
quests[27752] = { id = 27752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Like a Wildhammer", description = "S'not a boast to say that we Thundermars brew the finest ale in the Eastern Kingdoms. It's 220 proof. Yeah, you heard me!\n\nAs folks fled from the south to the town center, they were forced to leave behind their ale.\n\n<Blundy pauses, allowing the gravity of the situation to soak in.>\n\nGET IT BACK! That stuff'll turn even the stringiest of warriors into a whirlin' dervish of mouth-foaming destruction. Get them kegs! S'our only hope!", sourceObjective = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Careful - it's got some kick!", progress = "Get me that ale, {name}.\n\nHey, you haven't been skimmin' off the top, have you?", completion = "Oh aye ... we get a few of these kegs out to the boys on the front and we're gonna see some fireworks. Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27753] = { id = 27753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Leave a Dinner Behind", description = "Supplies are short, {name}. We've got refugees coming into Thundermar from up and down the ridge - that's a lot of mouths to feed.\n\nPlenty of food stores were left behind as people pulled their families to safety. We need that food!\n\nScour the Thundermar ruins south, east, and southwest of here for food stores.\n\nCareful, {class}! The fighting around the ruins is pretty intense.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Got some eats?", completion = "It's good - hardly a worm or weevil to be found!\n\nThis is a lifesaver to the folk who fled here for survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[27754] = { id = 27754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Takedown", description = "The Dragonmaw!\n\n<Colin spits.>\n\nMonsters, all of them. We've fought them up and down these highlands since the last war. And now they're joining forces with the Horde?\n\nIf you're going to convince us Wildhammers to unite under the Alliance banner, you'd best prove yourself against the Dragonmaw. Wade into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear. Then we'll talk.", sourceObjective = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "How goes the fight, {class}?", completion = "Look at that! That's quite a collection of trophies you have there.\n\nI'll spread the word. If a single Alliance {class} can do this, imagine what the rest of your lot can accomplish!", sourceObjectiveStatus = "unverified-source-field" }
quests[27755] = { id = 27755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of the Tombs", description = "The Neferset are not the only threat to our sacred tombs.\n\nA gnomish expedition stumbled upon our lands a few weeks ago.\n\nThey did not heed our warnings and dug too deep within a cursed vault.\n\nTheir entire expedition is now afflicted by a terrible curse that has robbed them of their sanity and taken control of their minds.\n\nThey now seek access to the deepest vaults of Uldum and pose a great threat. \n\nGo to the Sunstone Terrace and put their wretched souls out of their misery.", sourceObjective = "Slay 6 Crazed Diggers and Mekgineer Mixeltweed.", progress = "Is it done, {name}?  The expedition members cannot be saved.", completion = "They couldn't be saved, {name}.  The ancient curse that fell upon them is irrevocable.", sourceObjectiveStatus = "unverified-source-field" }
quests[27756] = { id = 27756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foreman", description = "If we're to find out what's going on down here it looks like we're going to have to fight our way through the entire Deadmines! Glubtok the Foreman will be the first major foe you encounter, a powerful ogre magi. Be careful, he possesses the brute strength of his race backed by his wicked spellcasting!\n\nTake this communicator so that I can keep in touch with you as we continue our investigation. Be careful down there.", sourceObjective = "Kill Glubtok.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nNicely done! A clean kill. Now continue on and see what else you can find! We'll crack this case wide open with you on our side, I just know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27757] = { id = 27757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkest Depths", description = "I've been seeing sea creatures acting oddly through the whole swamp. The murlocs, yes, but before that the gilblins, and the makrura... I even saw some naga wander ashore the other day.\n\nSomething's calling them here, and working them into a frenzy to boot. Many of the creatures have been drawn to Stagalbog Cavern to the west. Something's down there, and if it gets any stronger we'll all start wandering in there too...\n\nYou should put a stop to whatever it is before that happens.", sourceObjective = "Slay Hr'nglth the Lost.", completion = "Oh my. It sounds like you ran across quite a sinister being. I wonder what one of those was doing all the way out here...", sourceObjectiveStatus = "unverified-source-field" }
quests[27758] = { id = 27758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Carpenter", description = "<Bzzzzzzzzzzzzt.>\n\nHello, can you hear me? Excellent!\n\nIt looks like Helix is in charge of building an enormous mast. You don't think they're trying to finish the Defias Juggernaut, do you?\n\nYou'd better go investigate {name}, and don't be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let's face it, it's probably going to be necessary.", sourceObjective = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nHey, it's Horatio. That was intense! I'm watching your progress on the Stormwind Communicator's Spyatron X3 application.\n\nThey sure are using a lot of heavily fortified doors to hide their work. Keep pushing forward and see what you find next. I bet it'll be a huge clue!", sourceObjectiveStatus = "unverified-source-field" }
quests[27760] = { id = 27760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artificial Intelligence", description = "<A feminine voice addresses you over the portable terminal.>\n\nEmergency code: 55-729.\n\nUpper cerebral cortex functions in expedition members have been compromised.\n\nPlease report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.", sourceObjective = "Speak to the A.I.D.A. terminal at the Surveyor's Outpost  in Uldum.", progress = "<The terminal whirrs as its mechanisms become active.>", completion = "Scanning subject...\n\nCerebral cortex diagnostics indicate the absence of \"tomb curse\" phenomenon.\n\nDiagnostics did reveal frequent head trauma.  The user would do well to exercise more caution around blunt objects in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[27761] = { id = 27761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disarming Distraction", description = "The curse has taken over the expedition members' higher brain functions, but my calculations reveal their suppressed adolescent subconscious can still be stimulated by realistic imagery.\n\nUtilize this holo-projector to distract them.\n\nThey are currently setting up explosives at the tomb to the east to attempt to gain access to secret passages in Uldum.\n\nThey seek dangerous re-origination technology beneath Uldum and must be stopped.", sourceObjective = "Disarm the First, Second and Third Bomb Clusters and deactivate 4 Unstable Bomb Bots at the Tomb of the Sun King.", progress = "Greetings, user {name}.  I am happy to see you are still unaffected by the effects of the expedition curse.", completion = "Well done, {name}.  The expedition has already doomed itself.\n\nThere is no need for it to endanger the rest of the world as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27762] = { id = 27762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuselight, Ho!", description = "Hey, {race}, listen up.  I got a job opportunity that you aren't gonna want to miss out on.\n\nWe been sent up here from Fuselight, a new goblin town way down in the Badlands.  Lots of money to be had down there, yes <sir/ma'am>.  And not nearly so many zombies... or uptight Argent paladin-types.\n\nNope, it's an untamed wilderness down there, and we're looking for someone like you to help us tame it.  Whenever you're ready... we'll be waiting.", sourceObjective = "Ride The Uncrashable to the Badlands, then report to Eddie Flofizzle.", completion = "Nice landing!", sourceObjectiveStatus = "unverified-source-field" }
quests[27763] = { id = 27763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fuselight Proper", description = "This, {race}, is paradise.  I've always wanted to live in a nice quiet town by the sea so I can focus on my explosions without any distractions.\n\nQuiet's not for everybody, though... 'specially the adventuring hero-type, like yourself.\n\nWe've installed a teleporter in the backside of town that'll take you up to the top of the cliffs.  From there, you can take the quick ride west into Fuselight proper, within the Badlands.\n\nThere should be more for you to do up there.  Tell 'em that Flo sent you.", sourceObjective = "Use the Teleporter in the back of Fuselight-by-the-Sea to port up the mountain, then report to Dolph Blastus at Fuselight in the Badlands.", completion = "Welcome to Fuselight!", sourceObjectiveStatus = "unverified-source-field" }
quests[27764] = { id = 27764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Request", description = "On to other matters.  I have a package that I need delivered.\n\nA young lady came by our town not long ago, looking for compressed blasting powder, a tempered mithril bomb casing, and some safety goggles.  Naturally, we had plenty of blasting powder and bomb casings to sell her, but the safety goggles were a little harder to find.\n\nLong story short, I've got the goggles, but she's already returned to her studies down in Lethlor Ravine.  Will you bring these down to her?", sourceObjective = "Bring Dolph's Package to Rhea at Lethlor Ravine in the Badlands.", progress = "Ahh... you've found me.  Good.", completion = "Thank you, {race}.  You may keep the goggles, as they have already served their purpose: they brought you to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27765] = { id = 27765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Sample: Wild Eggs", description = "I am experimenting with black dragons.  Specifically, I am interested in how they procreate.\n\nMy current experiments require plenty of black dragon eggs, which is why I am here in Lethlor Ravine.  I'd gather the eggs myself, but I think you'll benefit from helping me out.\n\nYou will find them along the edges of the ravine.  Beware the guardians that circle above - they do not appreciate stolen eggs.", sourceObjective = "Obtain 6 Wild Black Dragon Eggs.", progress = "Have you brought the eggs?", completion = "Thank you for gathering these so quickly, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27766] = { id = 27766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sample: Whelps", description = "I need another favor from you.  I need you to obtain the bodies of the black dragon whelplings that fly nearby.  Slay them, and bring the corpses to me.", sourceObjective = "Obtain 10 Scalding Whelp Corpses.", progress = "Have you done as I asked?", completion = "This grisly task was necessary, {name}.\n\nAll will be revealed to you soon.  For now, know this:\n\nI am no ordinary goblin.\n\nI serve a mistress of unimaginable power, and her motives here are not as dark as they might seem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27768] = { id = 27768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Two: The Bloodletter", description = "The trolls here perpetuate the fall of my brethren to the nightmare. They infect and corrupt green dragons with the blood of their foul god, and then harvest the evil that has grown within them. They are being farmed like livestock...\n\nThis disgusting savagery cannot continue. Return to where you left the Hall of Masks and take the other corridor towards the Butchery. Gomora the Bloodletter harvests corpses for these foul and evil rituals there. Take his undeserved life from him!", sourceObjective = "Slay Gomora the Bloodletter in the Butchery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27769] = { id = 27769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhea Revealed", description = "As I hinted earlier, I am no ordinary goblin.  You may have already guessed my true identity.\n\nAllow me to show you my true form.  As you have proven yourself trustworthy, I will also share with you the details of my plan.", sourceObjective = "Learn Rhea's true identity.", progress = "You are certainly impatient, {name}.", completion = "My true name is Rheastrasza, and I am an envoy of Alexstrasza herself, the Aspect of the red dragonflight.\n\nWith Deathwing currently occupied with other matters, we are going to find a way to redeem the black dragonflight.\n\nAnd you are going to help us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27770] = { id = 27770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Veil", description = "The black dragonflight was once noble.  They were the earth warders, protecting the very land itself.  How ironic that they would become the worst menace the land has known.\n\nI believe that there remains a sliver of hope, however, and so does my mistress.  The black dragonflight will live beyond Deathwing's treachery, and will soar as the noble earth warders once again.\n\nI wish to show you something.  Close your eyes, and I will reveal to you the final part of my studies.", sourceObjective = "Witness the final piece of Rhea's studies.", progress = "You are certainly impatient, {name}.", completion = "We will find a shred of good within these dragons, {name}.  Whether it is in the wild eggs you found, the bodies of the whelplings you slew, or the eggs that we have encouraged Nyxondra to lay... we will find an untainted black dragon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27771] = { id = 27771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Sample: Implanted Eggs", description = "Nyxondra is being held against her will.  She is hidden from her brood, right in the middle of their breeding grounds.  She lays eggs, but they will be taken away before she can see them hatch.\n\nCruel?  Perhaps... but not nearly as cruel as the treatment that their dragonflight showed my mistress.\n\nShow me that I can trust you, {name}.  Take Nyxondra's eggs, and bring them here.  You will need to beat Nyxondra into submission before you can take them.", sourceObjective = "Obtain 3 of Nyxondra's Eggs.", progress = "Remember, {name}... this is for the good of the black dragonflight.  We are here to redeem them, not to hurt them.  This is but a step in their recovery.", completion = "You have done everything that I have asked you, without question.  Our job here in Lethlor Ravine is done.\n\nIt is now time that I revealed everything to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27772] = { id = 27772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venerable Doctor Blam", description = "I made a calculated decision in revealing my identity to you, {name}.  I needed you to trust me, but I can no longer stay here in Lethlor Ravine, as my cover has quite clearly been blown.\n\nYou may be able to slip away unnoticed, however.  Here, take the results of our research, and bring them west.  At Agmond's End, you will find a gnome who knows what to do with these samples.\n\nHurry, {name}!  You mustn't loiter here any longer than necessary!", sourceObjective = "Bring the Black Dragon Samples to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Dr. H. Blam, at your service.  How can I be of assistance to you today?", completion = "Ooh!  Science stuff!  Let's see what you've got here...\n\nWild eggs?  Blech.  Useless.  These are never any good.\n\nOoooh, what's this?  Some sort of... pre-engineered egg?  This looks promising, but I don't want to know what Rhea had to do to get it.\n\nHmm... yes, some very nice corpses.  Very nice indeed.\n\nAlright, I'll see what I can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27773] = { id = 27773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Three: Prophet", description = "All that yet stands between me and the temple is Prophet Jammal'an himself. He is the leader of the Atal'ai trolls here, a foul manipulator.\n\nKnow that you do not face a mere crazed troll, {name}, but an instrument of forces beyond your darkest comprehension. Yet you do not fight alone; my strength and the will of the Green Dragonflight go with you.\n\nProceed to the Den of the Caller, left through the Hall of Ritual, and then down into the Hall of Bones. At the bottom, you will find Jammal'an.", sourceObjective = "Defeat Jammal'an the Prophet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27774] = { id = 27774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easily Swayed", description = "The most immediate threat to Fuselight is, without argument, the colony of ogres to the northwest.\n\nMost of our ogre neighbors used to be warrior-types, but it seems that more and more of them are practicing magic.  I won't have an army of ogre-magi at my doorstep.\n\nGo take out some of those Dustbelcher ogres.  Hopefully they'll get the picture and avoid messing with the might of Fuselight.", sourceObjective = "Slay 9 Dustbelcher ogres at Camp Kosh.", progress = "I'll feel much better when those ogres are gone.", completion = "I wonder where all of these ogre-magi are coming from?  Curious times, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27775] = { id = 27775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When the Going Gets Tough, Cheat", description = "I just can't get my invention to work!  Gah!\n\nThat's it, I've decided.  I'm going to cheat and use magic.\n\nWhat my invention really needs is a solid piston that's thin enough to fit through a narrow copper tube, but strong enough to withstand repeated impact without breaking.  The magical rods carried by those ogre magi to the north should work perfectly.\n\nFrom what I can tell, only the instructors carry the strong staves.", sourceObjective = "Obtain an Instructor's Rod from an Ogre-Mage Instructor at Camp Kosh.", progress = "I don't like to stoop to using magic on my inventions, but this is somewhat of an emergency.", completion = "A perfect fit!  My goat puncher is finally finished!", sourceObjectiveStatus = "unverified-source-field" }
quests[27776] = { id = 27776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Goat Time, Baby", description = "We have a little bit of a goat problem here in Fuselight, in case you haven't noticed.  They'll eat anything, and they seem to have taken a liking to the piles of cogs and gears that we tend to leave sitting around.\n\nIt's getting really annoying!\n\nYou'll find most of the billy goats wandering around the edge of town, near the cliff's edge.  Use this device on them to give 'em a little \"nudge\".", sourceObjective = "Use Garyanne's Goat Puncher on 12 Billy Goats in Fuselight.", progress = "It's their own fault for standing so close to the edge", completion = "Well done!  I have no doubt that those goats will be back, but they'll think twice before they nibble my cogs again!", sourceObjectiveStatus = "unverified-source-field" }
quests[27777] = { id = 27777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Access Codes", description = "The expedition's numbers are extremely large, user {name}.\n\nDealing with them by conventional means would take you an estimated 2,700,136.5 hours.\n\nWe can make use of a powerful source of energy held within expedition's crawler vehicle.\n\nWe will need the fusion core's access codes to accomplish this.\n\nMekgineer Twizzleflux has these codes and can be found at the Starwatch Tower to the southeast.\n\nI've uploaded jamming frequencies to a scrambler.  Use it to temporarily disable Twizzleflux's defenses.", sourceObjective = "Obtain the Core Access Codes from Twizzleflux the Insane.", progress = "Did you succeed, {name}?  I estimated your chances of survival at 68.5%.", completion = "Excellent job, user {name}.  We must obtain access to the fusion core now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27778] = { id = 27778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Wibson", description = "It is true.  New expedition crews have arrived by sea.\n\nMy scanners detect that they already have been afflicted by the curse phenomenon.\n\nYou must hurry and go aboard the M.A.C. Diver.  The access codes will give us control over the fusion core's functions, but there is still a layer of security we must bypass.\n\nUser {name}, I must ask you to hack a very sophisticated mainframe known as the \"Wibson.\"\n\nDo not worry I will provide you with further instructions.", sourceObjective = "Hack the Wibson Mainframe on top of the M.A.C. Diver.", progress = "Greetings, user {name}.", completion = "I am in control, user {name}.  But I cannot keep the core temperature stable indefinitely.", sourceObjectiveStatus = "unverified-source-field" }
quests[27779] = { id = 27779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomebliteration", description = "I have downloaded my program to the fusion core and have complete control over it.\n\nI've created a small pocket of air inside to avoid vaporizing user {name}.\n\nI will yield control of all movement functions so I can dedicate my cycles to keeping the core stable.\n\nGo down the hill and neutralize as many of the expedition members as possible.\n\nMy analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers.\n\nUser {name}, you must be assured that expedition members are without hope.", sourceObjective = "Obliterate 1000 Crazed Gnomes.", progress = "The expedition members' demise is unfortunate.", completion = "It is done, user {name}.  I thank you for your assistance with this unfortunate task.", sourceObjectiveStatus = "unverified-source-field" }
quests[27781] = { id = 27781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Machination", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHe-hello? {name}, are you there? Are you still alive? Hello?\n\nOh good, you're still there! What in the name of Lordareon are they building? It's some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! \n\nThrow out the rules, do whatever you have to do to thwart them!", sourceObjective = "Destroy the Foe Reaper 5000.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nYou're nearing the heart of their domain. There will likely be an extremely fortified door protecting the inner sanctum of the entire Defias operation. See if you can find anything that might pry it open!\n\nI suggest a stealthy method!", sourceObjectiveStatus = "unverified-source-field" }
quests[27782] = { id = 27782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Mathias says he needs you.\n\nHe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", sourceObjective = "Speak with Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. We know where Cho'gall's ultimate weapon is located!", sourceObjectiveStatus = "unverified-source-field" }
quests[27783] = { id = 27783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Garona says she needs you.\n\nShe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", sourceObjective = "Speak with Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. It's about time. We know where Cho'gall's ultimate weapon is located!", sourceObjectiveStatus = "unverified-source-field" }
quests[27784] = { id = 27784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\nMany SI:7 died to bring us this information.", sourceObjective = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", sourceObjectiveStatus = "unverified-source-field" }
quests[27785] = { id = 27785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral", description = "<Bzzzzzzzzzzzzt.>\n\nI can't believe it...they're almost done rebuilding it! We don't have much time, {name}.\n\nAdmiral Ripsnarl, Vanessa's right hand man, is bound to be on board. We'll never get to her if he's still alive to do anything about it. You're going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa's private quarters on the top deck.\n\nBe careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!", sourceObjective = "Kill Admiral Ripsnarl.", completion = "<Bzzzzzzzzzzzzt.>\n\nYour exploits have gained quite the following in the intelligence community, {name}. Many top members of SI:7 have been earnestly watching you infiltrate the Deadmines through their own Stormwind Communicators.\n\nMathias Shaw himself wants to speak with you! I'll transfer you over momentarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[27786] = { id = 27786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\n<Garona begins sharpening her blades.>\n\nMany Kor'kron died to bring us this information.", sourceObjective = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", sourceObjectiveStatus = "unverified-source-field" }
quests[27787] = { id = 27787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", sourceObjective = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, lad! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27788] = { id = 27788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", sourceObjective = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, {name}! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[27789] = { id = 27789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggish Troubles", description = "I'll need some time to analyze these samples, as well as a break from this trogg-shooting duty.  Go man one of my turrets and take out as many troggs as you can.  I'll be here studying.\n\nThe turrets have two abilities: a regular shot, as well as an electrical overload, for when too many enemies get close!  Heh, heh.  Good luck.\n\nOh, and look out for the big, slow troggs.  You probably don't want to let them anywhere near you.", sourceObjective = "Enter a Blam Turret, then survive four waves of trogg attacks.", progress = "Not quite done yet.  Need some more time.", completion = "The results are in.  I've identified traces of corruption in all three samples you brought me.  Rhea will be quite disappointed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27790] = { id = 27790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "Hello there, {name}. I've heard a great deal about you. Listen closely, you're only going to have one solid shot at this.\n\nThe new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized.\n\nI'm shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we're in luck.", sourceObjective = "Kill the Defias Kingpin.", completion = "You very well may have saved all of Stormwind with your efforts here today, {name}. Vanessa may still be out there, but she is an insignificant threat now that the Juggernaut will be placed under our careful watch. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27791] = { id = 27791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dustwind Dig", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Explorers' League has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to Lead Prospector Durdin at the camp to the north.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", sourceObjective = "Speak with Lead Prospector Durdin at Dustwind Dig in the Badlands.", completion = "Titans?  You wanna know about titans?\n\nYou came to the right place, lad.  We're on the brink of somethin' big.", sourceObjectiveStatus = "unverified-source-field" }
quests[27792] = { id = 27792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Fair in Love, War, and Archaeology", description = "First things first, though.  I'm not just going to sit here and tell you everything we've discovered down in those ruins.  We've got problems to take care of!\n\nMost pressing is those upstart Reliquary hooligans, just on the other side of the tomb.  They're makin' off with all of our loot!  Don't they know that diggin's dwarf work?\n\nHunt down a few of their \"excavators\" - more like bandits, if you ask me - and bring some of these precious artifacts back to me.\n\nTHEN we'll talk titans.", sourceObjective = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "Your bags look heavy.  Heavy with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nAlright, fine.  Let's talk titans, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27793] = { id = 27793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", sourceObjective = "Investigate The Warden and The Sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27794] = { id = 27794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", sourceObjective = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27795] = { id = 27795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "The battle's proceeding just the way I wanted it. With their warriors nearly exhausted, I've sent in our cavalry.\n\nWhat I wasn't expecting was ogres. Our knights are well matched against the brutes, but they're going to need help.\n\nI need you back on the field right away, {name}. Few can bring down an ogre on foot, but I think I can count on you. Don't disappoint me.", sourceObjective = "Slay 6 Stonard Ogres.", completion = "Going toe to toe with ogres is impressive, {name}. I'm glad I've got soldiers like you out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27796] = { id = 27796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "Once those Reliquary honks got here, we panicked, and we all just started looting indiscriminately.\n\nA lot of bad archaeology happened that day.\n\nLuckily, Olga happened upon this small jade statue.  We thought it to be a key of some sort, but can't figure out what it opens.  Maybe you'll have some better luck with it.", sourceObjective = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27797] = { id = 27797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We very nearly had this statue stolen from us by one of Bloodwatcher's Reliquary stooges.  We managed to catch him in the act, and we've retrieved the statue, but it hasn't really paid off.\n\nIt appears to be a key of some sort, but I can't find the lock anywhere inside those ruins.  You feel like giving it a try?", sourceObjective = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue slides into place on the cold marble slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27798] = { id = 27798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen take your information and be gone from my demesne.", sourceObjective = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[27803] = { id = 27803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome Relief", description = "I've got boys formin' defensive lines on all sides of the town, keepin' back the elementals streaming from the torn ground. They're good lads and they've been holdin' firm, but even the sturdiest dwarf tires eventually.\n\nThey're split into shifts: one hour of rest for every hour on the line. Best I can get'm with the men we have.\n\nIf you want to be helpin', pick a line and take up a shift. Give some of my boys a welcome breather. Report back in once you've killed several of the elementals.", sourceObjective = "Kill 8 Subjugated Firestarters.", progress = "Don't be dallyin'. These men are pourin' every fiber of their bein' into holding this town, and I'll not see them insulted by the presence of anyone that won't hold their weight.", completion = "Good work, boy. Good to have another capable set of hands about.", sourceObjectiveStatus = "unverified-source-field" }
quests[27804] = { id = 27804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Homes We Have", description = "We've already been pushed back farther than I'd hoped, but I'm not about to give up our homes to these mongrels. They may burn them, pillage them, and spit on the rubbled remains, but we'll still fight to take them back.\n\nThat being said, I rather like them not burnt. I have the boys running buckets from the well to try to keep the fire down. If you'd join them, they can help out by tossing you buckets so you don't have to make the runs.", sourceObjective = "Extinguish 50 fires at Firebeard's Patrol.", progress = "As long as we work together, we can overcome anything the Twilight's Hammer might throw at us.", completion = "Thanks for your help. Every little bit makes a difference.\n\nWe'll keep the water going until we can push the Twilight back.", sourceObjectiveStatus = "unverified-source-field" }
quests[27805] = { id = 27805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Comforts", description = "You're the new face that's meant to be helping Keegan out I take it? Pleasure to meet you. Maybe you can lend a favor or two more to the troubled Wildhammer that have made refuge here.\n\nWe were all forced to retreat to this building quickly, and some of us left behind things of great value in our destroyed homes nearby. Would you mind bringing them back after you go out there? You would bring happiness to some very troubled souls.", sourceObjective = "Find and return Meara's Dried Roses, Parlan's Ivory Hammer, and Aprika's Doll.", progress = "Were you able to find their valuables? I know it seems so minor, but little things make a big difference to some people in times like these.", completion = "You are very generous. Thank you.\n\nThere's a lot of darkness in our world these days. We appreciate the light that you've brought here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27806] = { id = 27806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorable Bearing", description = "Iain, my second in command, bore the body of one of our fallen heroes to the cathedral to the west. He's the man I've put in charge of reforming a wing of gryphon riders from whatever scattered forces he can find. I would like you to help him.\n\nI should impress upon you the urgency of this task. We will not be able to hold here forever; the Twilight's Hammer or the Dragonmaw orcs will eventually overwhelm us. Putting together an active gryphon wing may be our only hope for surviving these conflicts.", sourceObjective = "Speak to Iain Firebeard at the Firebeard Cemetery.", completion = "Greetings, {race}. Sent by Keegan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27807] = { id = 27807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Mullan", description = "If we're going to pull a full gryphon wing back together, we're going to need to move fast to gather the survivors before they leave or get picked off. I've got a bead on a few groups of riders that stuck together. I'm leavin' to find the Thundermar riders and the Moore riders shortly.\n\nThe Mullans were heading up west to the Crucible of Carnage last I saw. Go see if you can convince Duglas Mullan to join up with Keegan - he should owe him a favor or three.", sourceObjective = "Speak to Duglas Mullan at the Crucible of Carnage.", completion = "Iain sent ya?\n\nYou don't look like a Firebeard to me. Why exactly should I be listenin' to anything you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[27808] = { id = 27808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn as a Doyle", description = "The Doyle riders were last spotted convergin' in the trees to the south, on the border of the Obsidian Forest. They're a stubborn bunch and are likely to take some convincin' if they're going to join up with us.\n\nYour best bet with Keeland Doyle is to tell'm Cailin Longfellow's taken up shelter with us back at the town. Keeland's got a good soft spot for her and she just might be enough to convince him to drag all his boys along.", sourceObjective = "Speak to Keeland Doyle in the Highland Forest.", completion = "It seems the Doyles suffered the worst of the attacking Twilight drakes.\n\nIt's clear that they fought to the end: not a single rider's footprint more than a few yards from his gryphon. It's doubtful there were any survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27809] = { id = 27809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard Bellows", description = "I also need ya to seek out Mackay and his men on the other side of the Devouring Breach, at the Gorshak War Camp.\n\nThe Dragonmaw didn't survive the initial onslaught, and Mackay's lookin' to ransack what he can of their camp to supply our fight. There shouldn't be much convincin' necessary, but they'll likely want a hand wrappin' things up there before they make their way back to Keegan.\n\nGive'm a boot in the arse from ol' Iain if ya have to.", sourceObjective = "Speak to Mackay Firebeard at the Gorshak War Camp.", completion = "'Bout that time, eh? Help us wrap things up then.", sourceObjectiveStatus = "unverified-source-field" }
quests[27810] = { id = 27810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fighting Spirit", description = "Keegan wants the Mullans to take wing with'm eh? If there's a dwarf I'd fly for, he'd be it. Still, I don't get why he'd be sendin' an outsider to be recruitin' me - not right polite by my standards.\n\nI'm guessin' ya don't last 20 seconds with any of my boys, at the bar or in the battlefield. Prove me wrong. Take one of'm down in a fight and then I'll think about flyin' with ol' Keegan.", sourceObjective = "Challenge and defeat one of the Mullan Gryphon Riders.", progress = "Naw, I'll not be fightin' ya. Get in there and challenge one of my boys if you've got a gut on ya at all.", completion = "That's the stuff! Not half bad. You've got a bit of fight in ya after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27811] = { id = 27811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Battle", description = "Don't let Duglas fool you, the Mullans have been itchin' to take wing again, and if there's anyone we'd do it for, it's Firebeard.\n\nWe left our gryphons in the Highland Forest to the south to hunt and to get away from the sounds of battle for a bit. They deserved a rest.\n\nIf you want us back in the air soon, you'd do well to help us bring our gryphons back in.\n\nTake this piece of charred highland birch. We use it during training - as soon as they smell it, they'll come straight back to us.", sourceObjective = "Find 8 Mullan Gryphons and dispatch them back to their gryphon riders.", progress = "We're not going to be much use to you without our birds.", completion = "Good on you. I always feel like a part of me is missing when my gryphon isn't nearby. I can't speak for Duglas or the rest of the clan, but I'll be ready to ride at Firebeard's call.", sourceObjectiveStatus = "unverified-source-field" }
quests[27812] = { id = 27812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loyalty of Clan Mullan", description = "Your point's made. Keegan can count on us. We'll meet'm back at town as soon as all the boys are rallied up.\n\nYou're tough for not bein' a Wildhammer. Guess they breed'm good where you come from too.\n\nStill, haven't seen ya drink yet. That'll be the real test.", sourceObjective = "Return the news on Clan Mullan to Iain Firebeard at the Firebeard Cemetery.", completion = "Ya got the Mullans. Good news! They're worth more than their weight in a fight, and they ain't exactly skinny.", sourceObjectiveStatus = "unverified-source-field" }
quests[27813] = { id = 27813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Worthy of a Dragonmaw", description = "The Twilight sacked this town, killin' most of the Dragonmaw that lived in it. A few survived though, and they're not right keen on us takin' liberties with their supplies.\n\nNot that that matters much.\n\nWell, I'm not right keen on them attackin' my boys. Kill'm off, chase'm out - I don't care, just get'm gone.", sourceObjective = "Defeat 6 Dragonmaw Stragglers.", progress = "Clear this place out for me yet? Not lookin' like it.", completion = "That's more like it. Let's finish gatherin' up supplies and get back to Keegan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27814] = { id = 27814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything We Can Get", description = "Stay back and forge more weapons?  Pah!  A Forgehammer has ne'er been afraid of battle!  Who needs the safety of home to make weapons?  Besides - there is oodles of raw material out here.  Those Dragonmaw weapons are worthless, but they can be smelted down to make actual weapons.  Bring me 8 Dragonmaw weapons so me daughter and I can forge real weapons out of them.", sourceObjective = "Bring 8 Dragonmaw weapons to Brom Forgehammer at Gorshak War Camp.", progress = "How many have you got so far?", completion = "Yer a good lad.  Have me thanks and a little gold for yer troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27815] = { id = 27815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somethin' for the Boys", description = "Cleaned up the camp and ran errands for Forgehammer?  Not bad for a wee {class}.  Take these to Iain at Firebeard Cemetery, and he should reward you for a job well done.", sourceObjective = "Bring Forgehammer's weapons to Iain Firebeard at the Firebeard Cemetery.", progress = "What have we here?", completion = "Hah! Looks like their raid went mighty well then. I'll have to buy ol' Forgehammer a round once we finish with this mess.", sourceObjectiveStatus = "unverified-source-field" }
quests[27816] = { id = 27816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Request", description = "Shame about the Doyles. It's a fair miracle that as many of us made it out as is though, so can't count it as much of a surprise.\n\nThose louts at Thundermar are cowards. Even after tellin' them it was Keegan askin', they won't set foot outside of their town. I did rope in the Moores though, so that's at least three clans' worth.\n\nKeegan wanted to hear from ya personally when you returned. Go find'm in town.", sourceObjective = "Speak to Keegan Firebeard at Firebeard's Patrol.", completion = "It seems you had some luck bringin' riders back. Well timed too - we just pushed the elementals back, so we should have the arm room to lead an attack right away.\n\nThank you, {name}. You're a good {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27817] = { id = 27817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping the Hammer", description = "Thanks to you and Iain, we've got enough riders together that we can take the fight back to the Twilight.\n\nWe're trained to fight while ridin', but a second rider to handle the Stormhammer tends to be more efficient. I thought you might enjoy the honor.\n\nPick your gryphon and join the fight. Best be quick about it though - we're aimin' to clear every last one of those Twilight off of those floatin' rocks before the hour's out.", sourceObjective = "Kill 12 Twilight Stormbenders and Servias Windterror using one of the gryphons at Firebeard's Patrol.", progress = "Today is the day that the tables turn.", completion = "Now that's how it's done, lad!\n\nWith a real gryphon wing back together, we can take the fight to the rest of the Twilight. You're welcome to fly with us anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27818] = { id = 27818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Signs", description = "I settled here well before Bogpaddle was founded, to brew my potions and find some peace and quiet. I know this swamp like the back of my old, gnarly hand.\n\nThere's been a change in the wildlife recently. Those winged snakes you may have seen in the stagalbog are wind serpents, and they haven't been seen around here for ages.\n\nThey're also prime for ingredients if they're the kind I'm thinking of. Be a dear and gather me some of their hearts, will you?", sourceObjective = "Collect 5 Intact Stagalbog Serpent Hearts.", progress = "Don't be squeamish now.", completion = "Let's have a look then...\n\nMmm, oh dear. That's what I thought these were. They might still be usable, but it's horrid to have such things in my backyard.", sourceObjectiveStatus = "unverified-source-field" }
quests[27819] = { id = 27819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST - RVM" }
quests[27821] = { id = 27821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "With war raging across the entire world, the last thing we need is a Horde settlement right in our backyard. Redridge, Duskwood, even Elwynn itself are all a day's march from here.\n\nWe've made the first strike, and I don't plan to give the Horde a chance to catch their breath. So consider yourself deployed. Grab a weapon, join the rest of the troops out in the Bloodmire, and start killing orcs.\n\nReport back here after you've done some damage. I want you back alive...and that's an order. Dismissed!", sourceObjective = "Slay 8 Stonard Warriors.", completion = "More black on you than red... that's what I like to see. Looks like you've got what it takes, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27822] = { id = 27822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "I want victory to be totally assured here. Having more resources isn't enough; we need to make sure the enemy has nothing.\n\nStonard's forces depend on the lumber gathered from the surrounding woods. The orcish peons that chop the lumber may not be warriors, but they still know nothing but hate for humans.\n\nShow no mercy. I want those peons killed and the supply of lumber to Stonard cut off completely.", sourceObjective = "Slay 5 Stonard Peons.", completion = "We've had strikes on our own lumber line while you've been gone. This should at least put us on equal footing for gathering rates.\n\nGood work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27823] = { id = 27823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dwarf's Got Needs", description = "I can appreciate a good diggin' as much as any other dwarf, don't get me wrong.  It's just that... well, we do so much diggin', and so little drinkin', that sometimes I wonder if I should just hang up me shovel and head back to Ironforge.\n\nBut not today.  I've got some diggin' in me yet.\n\nThose Dark Iron dwarves at Hammertoe's Digsite - just north of here - make some powerful fine beer, right here in the desert.  You think you could pick up a few for me?", sourceObjective = "Obtain 15 mugs of Shadowstout.", progress = "<Sigrun licks his lips in anticipation.>", completion = "<Sigrun instantly downs a dusty mug of shadowstout.>\n\nWow, this stuff is strong!  I knew they had beer, but I never expected them to have shadowstout!  That's my favorite shadowbeer!", sourceObjectiveStatus = "unverified-source-field" }
quests[27824] = { id = 27824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Stuff", description = "I've got a little proposition for you, if you're interested.\n\nThose Dark Irons were here before Durdin and his crew arrived.  That means that, once these titan ruins opened up, the dark irons were the first ones in there, lootin' all the good stuff.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nYou've more than proven your ability to wallop a dwarf.  Head on into that fortress and wallop your way to titan treasure.\n\nI'd go with, but I'm drunk.", sourceObjective = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "Now here's some treasure!  I was beginning to worry that these weren't titan ruins at all!\n\nI'll show these to Durdin.  Thanks again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27825] = { id = 27825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on what would be our hunting grounds, we have no way to get food.\n\nThe ogres to our southwest, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", sourceObjective = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27826] = { id = 27826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dragon's Mouth", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get this back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover pretty well when she transformed into her true form in front of all those whelps.  She's now in the west, staying at an Alliance camp called Dragon's Mouth.\n\nShe'll be waiting for you.  And for that egg.", sourceObjective = "Bring the Purified Black Dragon Egg to Rhea at Dragon's Mouth in the Badlands.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27827] = { id = 27827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swift, the Fierce, and the Stout", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nTalk to Eric, over on the other side of camp.  He and his brothers will be joining you.", sourceObjective = "Speak with Eric \"The Swift\" at Dragon's Mouth in the Badlands.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", sourceObjectiveStatus = "unverified-source-field" }
quests[27828] = { id = 27828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric, the Utility Dwarf", description = "Before we get too crazy what with the dragon-killin', let me tell you a little bit about how I fight.\n\n\"The Swift\" is what they call me, and here's why: I'll dash straight into your enemies - helmet first, mind you - and stun 'em for a few seconds.  I also keep a few potions with me for tight spots.\n\nWhy don't we practice fightin' together?  Head out into the field, and try out my abilities.", sourceObjective = "Use Eric's Charge and Eric's Pocket Potion.", progress = "We're not through yet, {name}.", completion = "I'm not what you'd call \"very strong\" or \"battle-hardened\", but I get the job done my own way.\n\nLookin' forward to fightin' with you.  I never fought with a fancy-lookin' {class} before.", sourceObjectiveStatus = "unverified-source-field" }
quests[27829] = { id = 27829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, northeast of Dragon's Mouth.  Hunt him down and defeat him.  You will likely need the help of your new dwarven allies.", sourceObjective = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!", sourceObjectiveStatus = "unverified-source-field" }
quests[27830] = { id = 27830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  It appears that they've taken over a large portion of New Kargath, the large Horde settlement northwest of Dragon's Mouth.  Their troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.\n\nWe dragons do not take part in the squabbles between Horde and Alliance, but I do understand the risk you take in entering New Kargath.  Please, heroes... be careful.", sourceObjective = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27831] = { id = 27831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", sourceObjective = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[27832] = { id = 27832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", sourceObjective = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27833] = { id = 27833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "I'd say we have a dragon problem, but it seems like they're a little more interested in New Kargath than they are in our small encampment.  Nevertheless, I've got top men focused on keeping the dragons at bay.\n\nOne problem that has gone unchecked, however, is the ogre camp to our southwest.  A small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier.  Thin their ranks before they thin ours.", sourceObjective = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "Thank you, {race}.  However, I'm afraid I don't have much to give you, other than this passionate round of applause.\n\n\n\nOh, I do have these.  Here, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[27834] = { id = 27834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baelog, the Glass Cannon", description = "Before I start droppin' arrows on those dragons, I'd better introduce myself.\n\nI'm Baelog, the muscle of this group.  My sword bites like a crocolisk, and my arrows sing like banshees.  I tend to wear down quickly, however, and can't take as much punishment as either of my two brothers.\n\nYou give the word, and I'll send an aimed shot right through your target's heart.  I can also cheer my brothers on, sending 'em into a battle-fueled frenzy.\n\nWhy don't we go try fighting together?", sourceObjective = "Use Baelog's Valhalla Shot and Baelog's Warcry.", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, {name}.  You're getting the hang of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27835] = { id = 27835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olaf, the Big Fella'", description = "You may not have noticed, but I'm pretty big, as far as dwarves go.\n\nI make sure that my two brothers here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", sourceObjective = "Use Olaf's Shield Wall and Olaf's Mighty Shout.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Olaf is around.  Just let me know, and I'll protect you from the monsters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27836] = { id = 27836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Spread", description = "Slaying the foul creatures that plague the river will not be enough, {name}.\n\nA new generation of these monstrosities already threatens to spawn within our holy waters.\n\nSeek their foul eggs and destroy them.", sourceObjective = "Destroy 6 Slitherer Eggs.", progress = "Have you succeeded, {name}?", completion = "I thank you, {name}.  This will make our prophetic visions that much clearer.", sourceObjectiveStatus = "unverified-source-field" }
quests[27837] = { id = 27837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trespassers in the Water", description = "Shortly after Uldum's protective barriers fell, the Vir'naal river became afflicted with a terrible corruption.\n\nWhether it was brought here maliciously or accidentally is not of great significance.\n\nThe result is the same.  As the river becomes clouded so does our ability to peer into what the future holds for us.\n\nLook outside, {class}.  These foul creatures were never meant to live in the pristine waters of our river.\n\nSlay them so that the river may grant us visions once again.", sourceObjective = "Slay 8 Stillwater Slitherers.", progress = "You've returned, {race}.", completion = "Yes, {name}.  I can feel the disruption in the river fading.\n\nYet, I feel the source of this taint still lingers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27838] = { id = 27838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of the Corruption", description = "You might have dealt with the symptoms of our problem, {name}.  But I've been studying these foul beasts and the eggs are not laid here by them.\n\nThe stream from the current carries their eggs to the dam, but whatever is laying them will be found upstream.\n\nGo northeast, to the river's main source, and deal with the root of the corruption.", sourceObjective = "Go to the northeastern source of the Vir'naal River and slay Scalemother Hevna.", progress = "Is it done yet, {name}.", completion = "Yes.  The waters are clearing up.\n\nI am certain I will be visited by a vision before the High Council meets.\n\nBe warned, {race}.  My vote will only be swayed by what I see.\n\nYou might have helped us greatly here today, but if the vision sways me to make a case against war then that is the way my vote will be cast.", sourceObjectiveStatus = "unverified-source-field" }
quests[27839] = { id = 27839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Weapons", description = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories.\n\nKing Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors.\n\nMy scouts report that the Neferset are about to move a major shipment of looted weapons south of here.\n\nI've instructed the laborers you recruited to assist you.  Call upon them with this horn when you find the smugglers and recover the weapons.", sourceObjective = "Retrieve the Ancient Tol'vir Armaments", progress = "You've returned, {name}.  How did the operation go?", completion = "This is quite timely.  I will distribute these armaments to my best men and to the laborers that you recruited.\n\nI've a feeling they'll show as much courage as my best trained captains.", sourceObjectiveStatus = "unverified-source-field" }
quests[27840] = { id = 27840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the west, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", sourceObjective = "Collect 5 Draenethyst Crystals from the Fallow Sanctuary.", progress = "Do you have the crystals?", completion = "Thank you, {name}.  We, are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27841] = { id = 27841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Goblin Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27842] = { id = 27842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Beginning", description = "I miss the days when legions of powerful ogres marched by the Horde's side into battle, the pathetic Alliance cowering at their ferocity. Perhaps those days will return before I am gone to the ancestors.\n\nHowever, that is not the case now. An ogre magi, Glubtok, has joined forces with the despicable Defias Brotherhood and acts as Foreman over their mining operations. The pathetic fool! End his life for me, and for the spirit and glory of the Horde!", sourceObjective = "Kill Glubtok.", progress = "Yes?", completion = "Do not be alarmed, {name}. I am close to you, waiting in the shadows. You've done well.\n\nYou must continue the mission here - I am too valuable to risk my life against petty criminals like these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27843] = { id = 27843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "Just killing ogres won't be enough. The ogres themselves are being summoned onto the battlefield far too rapidly.\n\nI need you to go far behind the enemy line and seek out their summoners. The orcs are using warlocks to bring their reinforcements in.\n\nCut down the warlocks, and the portals should close. There aren't many of them; a quick, surgical strike should cripple the enemy.", sourceObjective = "Slay 3 Stonard Warlocks.", completion = "Once again, well done. With a few more pushes the battle will be ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27844] = { id = 27844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!!!", description = "The goblins you'll find working with the Defias are officially traitors to the Bilgewater Cartel, the Shattered Hand, and the Horde itself!\n\nI haven't yet been initiated into the Shattered Hand, so my loyalties lie strongly with my people. Helix Gearbreaker apparently has no time for such associations, and works on building a mast for the Defias Juggernaut. On behalf of Miss Mayhem and myself, would you kindly 'dispose' of Helix?", sourceObjective = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "My employers do not take kindly to traitors.\n\nOn the flip side, they are renown for their kindness towards the loyal! You deserve to be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[27845] = { id = 27845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "We've taken more than we've lost, but we've still lost too much. Too many brave have given their lives for the Alliance out there. I want to make sure they're given proper honors no matter how fierce this battle gets.\n\nTake these flags out with you and place one on any fallen soldier you see. The protective wards on them won't offer much protection against any defilement, but it's better than nothing. I'll be able to better judge how many we've lost from a distance, as well.", sourceObjective = "Use the Banner of the Fallen to mark 7 Fallen Marshtide Footmen.", completion = "Thank you, {name}. Those soldiers deserve better than to be left face down in the mud.", sourceObjectiveStatus = "unverified-source-field" }
quests[27846] = { id = 27846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Worgen Spirit in Darnassus' graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", sourceObjectiveStatus = "unverified-source-field" }
quests[27847] = { id = 27847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite There", description = "These prototypes are going to change the face of Horde warfare when I perfect them! The issue I've been having is that their power sources don't allow for complicated combat maneuvers or large frames, both highly desired traits when it comes to fighting Alliance.\n\nThe Defias, with some help from goblin traitors like Helix, have almost completed the Foe Reaper 5000, a massive golem that will actually work!\n\nWe can't have that going public, can we? I'll lose customers!", sourceObjective = "Destroy the Foe Reaper 5000.", progress = "Yes?", completion = "Brilliant! Now all I have to do is finish my work, and my Mayhem Reapers will cause...mayhem...on any Horde front!\n\nAnd there won't be any Defias knockoffs to steal my profits!", sourceObjectiveStatus = "unverified-source-field" }
quests[27848] = { id = 27848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Intentions...Poor Execution", description = "The Defias plan to finish their Juggernaut and use it to lay waste to Stormwind. It is a noble cause any true orc warrior would embrace without a single thought!\n\nVanessa's fault lies in her execution of their plan. The ship is poorly constructed, the crew practically untrained, and, worst of all, there's a worgen in their midst!\n\nHis name is Admiral Ripsnarl, and he must be mercilessly slain in the name of the Warchief. Lok'tar ogar!", sourceObjective = "Kill Admiral Ripsnarl.", completion = "It's a shame that he was both a human and a worgen. Had he been a proud orc warrior I'd have liked to charge into battle alongside such a fierce combatant.\n\nWe can speak of ill-fated desires another day. It is time to take what is ours from the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27849] = { id = 27849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonard", description = "This is it, {name}. We've made our final push into Stonard itself.\n\nI shouldn't have to remind anyone, but I'll say it anyway: We're not orcs, and we're not going to become them out of revenge or spite. Stonard will not be burned to the ground for us to dance on the ashes.\n\nNo, I want this done right. I want this surgical. Hold your head high and strike down any orc that picks up a weapon.", sourceObjective = "Slay 6 Stonard Defenders.", completion = "You've followed orders well, {name}. On behalf of the crown, I'm rewarding you for your bravery on the battlefield.", sourceObjectiveStatus = "unverified-source-field" }
quests[27850] = { id = 27850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "The Shattered Hand has laid mostly quiet for years now.\n\nNo more!\n\nYou will be the instrument of our rebirth, {name}. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind\n\nAny survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might!\n\nGo now, VanCleef's death will be your greatest triumph yet hero.", sourceObjective = "Kill the Defias Kingpin.", completion = "COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight!\n\n<Kagtha composes herself.>\n\nNo matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!", sourceObjectiveStatus = "unverified-source-field" }
quests[27851] = { id = 27851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Supply", description = "We may not be flattening Stonard into dust, but I don't want to have to go in there a second time.\n\nI want you to gather any supplies you see in the town while you're there. Without food, they won't have any fighters after more than a day.\n\nThere should be crates scattered all over town.", sourceObjective = "Seize 5 crates of Stonard Supplies.", progress = "What's the situation?", completion = "Good work, {name}. With this, it's only a matter of time until the orcs are fleeing for the portal or begging for surrender.", sourceObjectiveStatus = "unverified-source-field" }
quests[27852] = { id = 27852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "War rages in the swamp, {name}. Vicious humans have settled north of the city and brought an army to our doorstep.\n\nThere is nothing in this swamp for them. Their sole reason for coming here is to attack us, unprovoked. We will not give them the pleasure of victory!\n\nWe are undermanned and I need every able orc to take to the battlefield. Go, and slay as many humans as you can.", sourceObjective = "Slay 10 Marshtide Footmen.", completion = "We will fight to the last orc, {name}. I hope you'll keep yourself alive long enough to properly destroy these trespassers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27853] = { id = 27853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "We are outnumbered by the Alliance. In their fear they send an army to crush a single settlement. But we will not give!\n\nWithout resources, their soldiers will be at a disadvantage. Human peasants busy themselves in the woods outside Marshtide Watch, gathering lumber to rebuild their crumbling walls.\n\nDeny them the wood, and their lives.", sourceObjective = "Slay 5 Marshtide Peasants.", completion = "No true member of the Horde should find pleasure in killing such terrified weaklings... without challenge, victory has no true thrill.\n\nBut your dirty work has helped stave off the Alliance and protect our homes here. Be proud of your work for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27854] = { id = 27854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "We have suffered many losses, {name}. Dreadmaul Hold has sent ogres from the Blasted Lands as reinforcements, but they can only send so many; the Alliance attacks them as well, even as we speak.\n\nThe Alliance has countered our ogres with mounted knights, a strategy that served them well in the Second War. We will need our strongest warriors to turn the tide of battle!\n\nReturn to the Bloodmire, {name}, and bring down those knights!", sourceObjective = "Slay 6 Marshtide Knights.", completion = "You are a true champion, {name}, to take the lives of so many on the battlefield. I hope it will be enough to save Stonard.", sourceObjectiveStatus = "unverified-source-field" }
quests[27855] = { id = 27855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "The Alliance has brought in their mages to summon more reinforcements directly to the battlefield from beyond their fortress. This must be stopped!\n\nTheir numbers are few, but a single portal can turn the tide of battle. Attack their mages and shut off those portals!", sourceObjective = "Slay 3 Marshtide Mages.", completion = "With no link to the outside, the Alliance must rely on what they've brought to the swamp. We shall see if they can handle our home environment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27856] = { id = 27856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "Many warriors have met death to bring us victory, {name}. The fate of a true orc.\n\nI have seen the way the Alliance loots the bodies of our fallen, clutching at our goods like packrats. They will not defile our fallen heroes on this field.\n\nTake these wards with you to the Bloodmire. Place them on the bodies of our fallen warriors. I will be watching, to see how many have fallen, and to honor their sacrifice. Let us hope the spirits give us aid for our respect.", sourceObjective = "Use the Banner of the Fallen to mark 7 Fallen Stonard Warriors.", completion = "You honor both the dead and the living with your courage, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27857] = { id = 27857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Under Attack!", description = "The Alliance are at our walls!\n\nYour actions delayed them and weakened their forces, {name}, but in the end we are outnumbered. This is our last stand. Victory or death...\n\nFight with honor, {name}. They are within the walls as we speak. Drive the human dogs from Stonard, for the Horde!", sourceObjective = "Slay 12 Marshtide Invaders.", progress = "There is no time! Go! Fight!", completion = "The Alliance is driven out! Stonard will be safe, thanks to your ferocity. Lok'tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27858] = { id = 27858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27859] = { id = 27859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Egg Lives On", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", completion = "You were not the only mortal that Rheastrasza confided in.  I too earned the dragon's trust.\n\nI have already moved the real purified egg on to a safer location, away from the Badlands.  It will continue to grow, out of Deathwing's sight.\n\nThe red dragonflight is as benevolent as it is powerful.  It was Rheastrasza's final wish that I give this to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27860] = { id = 27860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Ones", description = "When the Dark Portal closed many years ago, regret and fear seized many of us who had come to these lands. In their despair, they cursed the name of the Light, and sank into violence and hatred.\n\nThese fallen souls are now the Lost Ones, little more than mindless monsters, attacking all who approach. They grow more corrupt by the day, and as they die off, they have begun to kidnap from the Harborage..\n\nThey are beyond help, {name}. Their suffering must end. Will you put them from their misery?", sourceObjective = "Slay 12 Lost Ones in the Fallow Sanctuary.", completion = "It still pains my heart to have asked you to do this, though I know there is no other way. You have saved those of us still holding on from a terrible menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[27861] = { id = 27861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", sourceObjectiveStatus = "unverified-source-field" }
quests[27862] = { id = 27862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "Well well, if it isn't the once champion of anguish, {name}! I'm seeing good money in the future now that you're here! We're gonna be rollin in the dough, buddy! Filthy RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", sourceObjectiveStatus = "unverified-source-field" }
quests[27863] = { id = 27863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[27864] = { id = 27864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Deadly Dragonmaw!", description = "You're going to love this one! The Dragonmaw heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on orc action! Let me know when you're ready to do this!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Torg Drakeflayer!", completion = "No love in your heart for orcs I see. You really made a mess of that guy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27865] = { id = 27865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Wayward Wildhammer!", description = "You're going to love this one! The Wildhammer heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on dwarf action! Let me know when you're ready to do this!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Sully Kneecapper!", progress = "No payout until the fight's over, man.", completion = "No love in your heart for dwarves I see. You really made a mess of that guy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27866] = { id = 27866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: Calder's Creation!", description = "Grim and gory, this next match is sure to have the crowd groanin' one way or another. Calder Gray has been gathering the bodyparts of defeated challengers and building the perfect champion.\n\nThis thing is the ultimate cobbled collaboration of corpsified combatants. A magnificent mashup of mangled monstrosities. Are you ready to get messy?! Cause I am! Let me know when you're ready so we can get this thing started!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat the Cadaver Collage!", progress = "No payout until the fight's over, man.", completion = "Wow! When I saw that... thing stumble into the arena, I thought you didn't stand a chance. But you proved me wrong. You tore it apart!\n\nGrizzly business.", sourceObjectiveStatus = "unverified-source-field" }
quests[27867] = { id = 27867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Earl of Evisceration!", description = "You're going to have your hands full with this one, pal. We've got a seasoned gentleman warrior here! He hails from Gilneas, and he's out to prove that he's the best warrior this side of Azeroth.\n\nYou better pull up those boots and zip up those pants, because it's going to get downright feral up in here. Give me the word when you're down for some punishment.", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Lord Geoffery Tulvan!", progress = "No payout until the fight's over, man.", completion = "You really pulled that one out. I thought you were done for sure when he wolfed and started tearing up the arena. I guess I should know by now that you don't go down easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27868] = { id = 27868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Twilight Terror!", description = "We've got someone you'll really love to hate this time around. I wasn't sure at first if I should let him into the pit, but a fight's a fight! And who am I to turn down some guaranteed cash?!\n\nThis guy hails from the Twilight Citadel itself, and comes toting a toasty punch. Better move fast and watch your back! Just give me the word when you're ready for some action.", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Emberscar the Devourer!", progress = "No payout until the fight's over, man.", completion = "Looks like this title is yours! You really pulled that one out of the fire. \n\nCongratulations. I hope the coin serves you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27869] = { id = 27869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon and the Temple", description = "These serpents must be from the Temple of Atal'Hakkar. I already had a hint...\n\nNot a few days ago, I had a visitor stop by and ask me to keep an eye out for such things. An elf by the name of Itharius. I'm sure he didn't think I could see through his form... he was a green dragon in disguise, come here to help his fallen brothers no doubt.\n\nHe may very well be on to something. Itharius left for the temple itself. Perhaps you'd better go look for him there. Dark things are afoot.", sourceObjective = "Speak with Lord Itharius atop the outer steps of the Temple of Atal'Hakkar.", completion = "The goblin sent you? She has a cunning eye, that one.\n\nShe speaks the truth. I am here to stem the tide of corruption seeping from this temple. If you would save your people from a wicked fate, {name}, I ask for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27870] = { id = 27870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Marshtide Watch", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nNorth of the temple, humans of your mortal Alliance have built what they call Marshtide Watch. They war with the Horde across the swamp, a raging conflict that I forsee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", sourceObjective = "Speak with Joanna Blueheart at Marshtide Watch.", completion = "Trouble within the temple... I wish we could spare forces to deal with it. The war with Stonard is already raging, and we need every man we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[27871] = { id = 27871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonard", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nSouthwest of the temple is the Horde town of Stonard. The orcs there wage war with the new human arrivals to the swamp, a raging conflict that I forsee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", sourceObjective = "Speak with Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", completion = "We have no time to send orcs to the temple, {name}. The humans come, and they are many. Stonard must be defended!", sourceObjectiveStatus = "unverified-source-field" }
quests[27874] = { id = 27874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana's Legacy", description = "Your expertise is needed elsewhere, {name}.\n\nJust southwest of the World Tree you will find the Shrine of Aviana, home to the Druids of the Talon. Aviana, the matron of all winged creatures, gave her life for this world ten thousand years ago.\n\nI sense her shrine is being threatened, as are the druids who guard it. Seek out Choluna, one of the wisest of the winged druids, deep within the shrine.", sourceObjective = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Ysera herself sent you to me? Oh! It's an honor to speak with a representative of the aspects.\n\nIt's true that our shrine is in jeopardy. The harpies we once sheltered in our boughs have suddenly turned against us.\n\nBut please, don't rejoin the fight until you are ready. Our shrine is no mere battleground. Use its peace and power to center yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27875] = { id = 27875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have worked for years to try to cure the affliction of the Broken. The foul energies that corrupted them did  more than twist their bodies; it took the comfort of the Light from them. They cannot feel its warmth.\n\nI cannot let Magtoor pass on in darkness, {name}. Before he worsened, I was studying prayerblossom, a flower that grows in the shifting mire. It grows hardy in even the darkest shade. I beg of you, gather these flowers for me, for Magtoor's sake.", sourceObjective = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "Prayerblossom has been used by the Broken as a remedy since they settled in this swamp. If it soothes the physical form, it might be used for more powerful healing...", sourceObjectiveStatus = "unverified-source-field" }
quests[27876] = { id = 27876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "The Shifting Mire takes its name from a unique phenomenon. By some force, the extremely fine silt will collect, and move on its own accord, travelling as if alive.\n\nI originally worried this was some corruptive force, but my studies have shown the opposite; whatever energy invigorates this soil is positive in nature. Perhaps such vibrant life can be imparted onto the Broken to reawaken what they once were.\n\nThe silt may not take kindly to being collected, {name}. But please, help gather it.", sourceObjective = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Did you get those samples?", completion = "It will have to be purified, but this will be most helpful. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27877] = { id = 27877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Morons' League", description = "I need your help in a little project I'm working on, {name}.  It falls into a realm I like to call \"defensive archaeology\".\n\nI like to bury non-magical items in conspicuous places to fool those Alliance idiots into thinking they've found something valuable.\n\nHmm... Dark Iron dwarves wander Hammertoe's Digsite and Angor Fortress, to the north.  Bring their heads back to me.  Yes, that's right, their heads.\n\nOnce the flesh is stripped, we can use those skulls to interfere with the dwarves' work.", sourceObjective = "Obtain 15 Dark Iron Heads.", progress = "<Lidia waits expectantly.>", completion = "Excellent!  We'll bury these immediately.  Those Explorers' League dimwits will never suspect us!", sourceObjectiveStatus = "unverified-source-field" }
quests[27878] = { id = 27878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forcible Acquisition", description = "I've got a little proposition for you, if you're interested.\n\nThe Dark Iron dwarves were here long before we arrived.  That means that, once these titan ruins opened up, the Dark Irons were the first ones in there, looting all the choice items.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nI want you to find such a treasure... then steal it.", sourceObjective = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "I knew it!  The High Examiner will be pleased to see this.\n\nNice work, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27879] = { id = 27879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on our hunting grounds, we have no way to get food.\n\nThe ogres to our south, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", sourceObjective = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27880] = { id = 27880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "My grunts have got this dragon problem under control.  Besides, I can't have an upstart {class} like you barging in and ruining our battle plans.\n\nYou want work?  Fine, I'll give you work.  Investigate the ogre camp to our southwest.  From what I've heard, a small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier... especially while we're already embroiled with black dragons.  Thin their ranks before they thin ours.", sourceObjective = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "You've got the hint of a hero in you, {race}.\n\nNow get out of my battlefield.", sourceObjectiveStatus = "unverified-source-field" }
quests[27881] = { id = 27881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodwatcher Point", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Reliquary has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to High Examiner Tae'thelan Bloodwatcher at their camp to the northeast.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", sourceObjective = "Speak with High Examiner Tae'thelan Bloodwatcher at Bloodwatcher Point in the Badlands.", completion = "Titans?  You come to me, asking about titans?\n\nYou've come to the right place, as we're on the brink of discovering something big.  You will, however, need to earn your keep first.", sourceObjectiveStatus = "unverified-source-field" }
quests[27882] = { id = 27882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not About History, It's About Power", description = "The Explorers' League may have a yeoman's knowledge of the actual act of digging.  What they lack, however, is the good sense to USE the artifacts that they dig up.  They stow their treasures in stagnant museums instead of using these items of power for their true purpose.\n\nThe dwarves are fools.  Fortunately, they die easily.\n\nYou'll find them digging into canyon walls north of here.  Take whatever you can out of their stubby-fingered hands, then return it to me.", sourceObjective = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "You've returned with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nWe must not be so hasty as to overlook the troggs.  They may be simple, but they know things about the deep, hidden places of this world.\n\nYou've performed well enough.  Let's talk titans, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27883] = { id = 27883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "One of the few items of worth that we managed to loot from these ruins is this small jade statue.\n\nWe believe it to be a key of some sort, but we're unable to determine what it opens.  As such, it is useless to me.\n\nPerhaps you'll have some better luck with it.", sourceObjective = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27884] = { id = 27884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We found this small red statue on the corpse of one of those Explorers' League archaeologists.  Sadly, it wasn't us who killed him.  The local wildlife had already taken care of that.\n\nThe statue is well-crafted, but apparently bereft of magical power.  You may use it for whatever means you deem necessary.", sourceObjective = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.", completion = "<The statue slides into place on the cold marble slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27885] = { id = 27885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", sourceObjective = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", sourceObjectiveStatus = "unverified-source-field" }
quests[27886] = { id = 27886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", sourceObjective = "Complete the Sentinel's Game by connecting the two red statues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27887] = { id = 27887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", sourceObjective = "Investigate The Warden and The Sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27888] = { id = 27888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", sourceObjective = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27889] = { id = 27889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Kargath", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get these back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover when she transformed into her true form in front of all those whelps.  She's now in the west, staying at a large Horde establishment dubbed \"New Kargath\".\n\nShe'll be waiting for you.  And for that egg.", sourceObjective = "Bring the Purified Black Dragon Egg to Rhea at New Kargath in the Badlands.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27890] = { id = 27890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad Dogs", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nI've paid off a couple of mercenaries to help you.  You'll find them inside this inn.", sourceObjective = "Speak with Amakkar at New Kargath in the Badlands.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", sourceObjectiveStatus = "unverified-source-field" }
quests[27891] = { id = 27891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amakkar, Jack of All Trades", description = "Before we get too crazy with the dragon-killing, let me tell you a little bit about how I fight.\n\nI'm not terribly strong or stalwart like these other two, but I've got a few tricks.  At your command I'll stun your enemies to keep 'em held still.  I also make sure to keep a few potions around for tight spots.\n\nWhy don't we practice fighting together?  Head out into the field, and you can see what it's like to fight with a real orc.", sourceObjective = "Use Amakkar's Kidney Shot and Amakkar's Pocket Potion.", progress = "We're not through yet, {name}.", completion = "I'm looking forward to fighting with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27892] = { id = 27892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jurrix the Striker", description = "Oh, you want to talk?  Fine.\n\nI'm Jurrix, the only merc here with half a brain.  The only one with any bite to my attacks, too.  The only reason I keep these meat shields around is to keep myself from getting killed.\n\nListen, you're the boss of this operation.  You give the word, and I'll send a fireball right through your target's heart.  If things start getting hectic, I can even warp time a bit so you can fit in a few extra attacks.\n\nWhy don't we go try fighting together?", sourceObjective = "Use Jurrix's Fiery Blast and Jurrix's Time Warp.", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, {name}.  You're getting the hang of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27893] = { id = 27893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargal, the Behemoth", description = "You may not have noticed, but I'm pretty big, as far as orcs go.\n\nI make sure that my two pals here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", sourceObjective = "Use Gargal's Shield Wall and Gargal's Mighty Shout.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Gargal is around.  Just let me know, and I'll protect you from the monsters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27894] = { id = 27894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, east of New Kargath.  Hunt him down and defeat him.  You will likely need the help of your new mercenary allies.", sourceObjective = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27895] = { id = 27895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  As you've probably already noticed, they've taken over a large portion of New Kargath.  These troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.", sourceObjective = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27896] = { id = 27896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", sourceObjective = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[27897] = { id = 27897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", sourceObjective = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27898] = { id = 27898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27899] = { id = 27899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Gleam in his Eye", description = "If you're looking for Harrison, you just missed him.\n\nHe was going on and on about his latest discovery, and how everything was beginning to make sense.\n\nWhatever... he certainly wasn't making sense to me.\n\nI tried to convince him to stay here and just enjoy a few desert sunsets with me, but there's no talking to him when he gets that gleam in his eye.\n\nPerhaps you'd be willing to check in on him?\n\nHe was headed to that big monolith, south of here.", sourceObjective = "Speak to Harrison Jones at the Obelisk of the Sun.", completion = "It would seem that I'm not the only one interested in these obelisks...", sourceObjectiveStatus = "unverified-source-field" }
quests[27900] = { id = 27900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got This Guy", description = "Good timing, {name}.\n\nSeems I'm not the only one interested in these obelisks, and these fellas aren't inclined to compare notes...\n\nI think I can handle this guy.\n\nMaybe you could take care of a few of his friends before they make their way over here?", sourceObjective = "Kill 10 Schnottz Air Troopers.", progress = "This guy's tougher than he looks - and he looks tough!", completion = "That's a relief. Thanks, {name}.\n\nTurns out I've got my hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27901] = { id = 27901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Don't Know What They've Got Here", description = "Listen, {name}. I don't have a lot of time to talk here.\n\nThese guys are excavating relics from this site and taking pieces of ancient technology that we need!\n\nI need you to check their crates for pieces of an ancient activation device. The officers should have the codes you'll need to open them.\n\nHurry!\n\nWe can't let them load this stuff into their planes!", sourceObjective = "Create the Titan Activation Device.", progress = "Have you got the titan activation device, {name}?", completion = "That's it!\n\nGood work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27902] = { id = 27902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Magtoor has told me of the shamanism that the Broken practice. The great Nobundo once said that the path of the elements may, in a way, be another way to the Light.\n\nI can only hope there is some truth in this. The elementals that gather near Purespring Cavern to the south are a source of truly pristine water. They can be chaotic and violent, but the pure water harvested from them will be the perfect conduit for the blessing of the Light.\n\nPlease, bring me this water, {name}.", sourceObjective = "Collect 6 Purespring Motes from Purespring Elementals.", progress = "Have the elements given up their source?", completion = "Such clarity... let us hope this will aid poor Magtoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27903] = { id = 27903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignition", description = "This guy just won't go down!\n\nYou're doin' great, kid. Only one thing left to do.\n\nAccording to my research, there should be a titan statue down below. Use the device to activate it, then break it down.\n\nIf my theory is correct, that statue holds the key to reactivating this obelisk.", sourceObjective = "Recover the Lens of the Sun.", progress = "Time to see if this old mechanism still works...", completion = "According to Harrison's notes, placing the lens upon this dais should re-activate this obelisk.\n\nExactly what that means remains to be seen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27904] = { id = 27904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Mist", description = "The Grell are forest spirits that wander the Misty Valley to the east. Though they resemble imps, I have found no demonic traces among the ones I've studied. They are, as far as I can tell, uncorrupted. \n\nThose that dwell in the valley move as one with the wind, summoning gusts of breeze at their whim. This pure air may be incorporated into my remedy for poor Magtoor.\n\nPlease, {name}, gather the smoky crystals found within the grells' bodies for me. I must exhaust every potential cure.", sourceObjective = "Collect 5 Smoky Crystals from Misty Grell.", progress = "Do you have the crystals?", completion = "I can only hope this will lead to a cure, {name}. Thank you for bringing it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27905] = { id = 27905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "Okay, I've softened this guy up, how about you help me finish him off?\n\nI've got a plan for our escape, but it'll require a lot of guts and a little luck.\n\nYou up for it, {name}?\n\nJust follow my lead...", sourceObjective = "Use the tailgun to defend the Schnottz Bomber.", completion = "Good work back there, {name}.\n\nLooks like we've lost them, for now at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[27906] = { id = 27906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Bloodscar", description = "There is much work to do in recovering from the assault and bracing ourselves for the next one. I will need coordination from all of our scouts.\n\nNeeka Bloodscar is our finest tracker, trained in the harsh Badlands. She has been sent west to Splinterspear Junction to watch for Alliance activity.\n\nGo to Neeka, {name}. Tell her of what has occured in Stonard. Assist her in any way she requires.", sourceObjective = "Speak with Neeka Bloodscar at Splinterspear Junction.", completion = "I hope the sight of my sniveling amuses you, {name}. It will be the only joy here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27907] = { id = 27907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have been ruined, {class}. I placed my strength in Helgrum, and now it bleeds from his gaping wounds. Wounds too deep to heal, flesh that refuses to knit.\n\nHe murmurs in fear, consumed by fever and pain. I cannot leave his side. Not now. Please, I ask you in shame to gather herbs for me.\n\nThe prayerblossom that grows in the swamp is an old remedy for soothing. With enough of it, his pain might be stilled.", sourceObjective = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "I will grind these and try to get him to eat. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27908] = { id = 27908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "Helgrum's wounds fester in the swamp air. They swell and ooze, filling his final moments with suffering. I must have something to coat them with.\n\nThe spirits move through this mire. They inhabit the mud itself, pushing it along in clumps of fine soil that take on lives of their own\n\nThe spirits of the cool, pure mud will offer him some comfort. Please, gather it for me, for I cannot abandon his side.", sourceObjective = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Helgrum still breathes. Do you have the mud?", completion = "At least I can soothe him with my own hands while he still breathes. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27909] = { id = 27909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Helgrum's breathing slows. His time is near.\n\nI need water. Elementals roam the ponds of Purespring Cavern. The water that flows from them is the purest in this swamp.\n\nEven if I could risk leaving Helgrum's side, my axe would shudder in my hand. I must beg you once again to pity me, for his comfort. Bring me the motes of the elementals, that his final drink may be pure and refreshing.", sourceObjective = "Collect 8 Purespring Motes from Purespring Elementals.", progress = "You've returned.", completion = "He can only drink so much. The rest might be used for washing his body, after...\n\n<Neeka glares in frustration and shudders, turning her head away.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27910] = { id = 27910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Regrets", description = "If I am reduced to groveling, I may as well ask everything I can. There is one last favor I would ask of you, one more task a shamed orc pleads for.\n\nHelgrum had a prized prey. Duskfang, eater of ogres, the great panther of Misty Valley. He would never allow himself the leisure of stalking it. Though he wanted badly to hunt, our scouting duties were too important.\n\nIf he cannot hunt Duskfang in this world, he can hunt the beast in the next. Take up the hunt for him; bring Duskfang's pelt to me.", sourceObjective = "Collect Duskfang's Hide.", progress = "Has Duskfang shown himself?", completion = "With Duskfang to shroud his body, he will carry the animal's spirit with him into the afterlife.\n\nListen to me. An old superstitious fool. I'm so sorry, Helgrum...", sourceObjectiveStatus = "unverified-source-field" }
quests[27911] = { id = 27911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Dying Breath", description = "He stirs...\n\nDo not leave, {name}. Please, honor Helgrum with me. You have done so much for him.", sourceObjective = "Witness Helgrum's last moments.", completion = "He is gone.\n\nHe is right. I must be strong for him...", sourceObjectiveStatus = "unverified-source-field" }
quests[27912] = { id = 27912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", sourceObjective = "Investigate the Trove of the Watchers.", completion = "You peer into the chest...", sourceObjectiveStatus = "unverified-source-field" }
quests[27913] = { id = 27913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", sourceObjective = "Investigate the Trove of the Watchers.", completion = "You peer into the chest...", sourceObjectiveStatus = "unverified-source-field" }
